-- =============================================================================
-- Publish BA flagship QUESTIONS into chapter_end exams. Competency at insert.
-- Governed by docs/standards/PUBLISH_LAYER.md ; contract: PUBLISH_MANIFEST.md.
-- Sources: seed-business-analysis-course (200 Qs, re-tagged to ba: §7 slugs) +
--   docs/curriculum/business-analyst-v1/questions/*.md (authored gap questions).
-- GENERATED FILE — do not hand-edit; regenerate from the authored sources.
-- Idempotent: only inserts a module's questions when its chapter_end quiz is empty.
-- REVIEWABLE SQL — apply by hand after the structure migration.
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.fill_ba_exam(p_mod int, p_payload jsonb)
RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE cid uuid; ch uuid; qz uuid; rec jsonb; i int := 0;
BEGIN
  SELECT id INTO cid FROM public.courses
    WHERE title = 'AI Business Analyst & Product Discovery Specialist' AND curriculum_version = 'ba-v1';
  SELECT id INTO ch FROM public.chapters WHERE course_id = cid AND order_index = p_mod;
  SELECT id INTO qz FROM public.quizzes WHERE chapter_id = ch AND quiz_type = 'chapter_end';
  IF qz IS NULL THEN RAISE NOTICE 'no exam for module %', p_mod; RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.quiz_questions WHERE quiz_id = qz) THEN RETURN; END IF;
  FOR rec IN SELECT * FROM jsonb_array_elements(p_payload) LOOP
    i := i + 1;
    INSERT INTO public.quiz_questions
      (quiz_id, question_text, options, correct_answer_index, explanation,
       order_index, competency, translations)
    VALUES (qz, rec->>'q', rec->'opts', (rec->>'a')::int, rec->>'exp',
       i, rec->>'competency', '{}'::jsonb);
  END LOOP;
END;
$fn$;

-- Module 1: 10 questions
SELECT pg_temp.fill_ba_exam(1, '[{"q":"What is the primary role of a Business Analyst?","opts":["Managing project timelines","Testing software","Writing code","Bridging the gap between business needs and technical solutions by defining requirements clearly"],"a":3,"exp":"BAs translate business problems into requirements that development teams can implement. They prevent the most expensive problem in software: building the wrong thing.","competency":"ba:requirements"},{"q":"What distinguishes a BA from a PM?","opts":["PMs are more senior","BA writes all documentation","PM manages HOW work gets done; BA defines WHAT needs to be built","BAs are more technical"],"a":2,"exp":"BAs focus on requirements, problem definition, and solution scope. PMs focus on schedule, budget, resources, and delivery. Both roles are essential and complementary.","competency":"ba:requirements"},{"q":"What is the cost of poor requirements?","opts":["Minimal — developers can figure it out","Only affects quality","Only affects timelines","Requirements errors are the most expensive to fix — catching in requirements costs 1x, in production costs 100x"],"a":3,"exp":"The IBM Systems Sciences Institute found defects found in production cost 100x more to fix than those found during requirements. BAs prevent expensive downstream failures.","competency":"ba:requirements"},{"q":"What is an IT Business Analyst?","opts":["A BA focused on IT system requirements — translating business needs into functional and non-functional specifications","A software developer","A project manager for IT","A data analyst"],"a":0,"exp":"IT BAs work closely with development teams on system requirements, user stories, acceptance criteria, and solution validation. They''re the product''s voice in technical projects.","competency":"ba:requirements"},{"q":"What is the most important BA skill?","opts":["Documentation ability","Technical knowledge","Communication and active listening — understanding what stakeholders really need, not just what they say they want","Domain expertise only"],"a":2,"exp":"BAs often hear ''I want X'' when the real need is ''I need Y.'' Active listening, probing questions, and empathy uncover true needs behind stated requirements.","competency":"ba:requirements"},{"q":"How can AI accelerate user story writing?","opts":["Describe the feature and user need — AI generates draft user stories with acceptance criteria for BA review and refinement","AI replaces the BA in story writing","AI writes perfect user stories autonomously","AI only formats existing stories"],"a":0,"exp":"AI provides starting material: describe a feature and get 5 user story options with acceptance criteria. BA validates against actual stakeholder needs and context.","competency":"ba:ai-analysis"},{"q":"How can AI help with requirements gap analysis?","opts":["Provide requirements to AI — it identifies missing scenarios, edge cases, and conflicts human reviewers often miss","AI cannot identify gaps","AI creates requirements gaps","Only for technical requirements"],"a":0,"exp":"AI reviews requirements systematically without fatigue. ''Review these requirements and identify missing edge cases, contradictions, and ambiguous terms'' produces useful gap analysis.","competency":"ba:ai-analysis"},{"q":"What is the risk of using AI for requirements generation?","opts":["AI makes requirements too detailed","AI generates plausible requirements that may not reflect actual business needs — stakeholder validation is essential","Only a risk for junior BAs","AI is always correct"],"a":1,"exp":"AI generates based on patterns, not organizational context. Requirements that sound correct may miss the organization''s specific constraints, policies, and real user behaviors.","competency":"ba:ai-analysis"},{"q":"How can AI meeting assistants help during elicitation?","opts":["AI conducts the interview","AI replaces note-taking entirely","Transcribe, summarize, and extract requirements from elicitation sessions — freeing the BA to focus on facilitation","Only for virtual meetings"],"a":2,"exp":"Otter.ai, Fireflies, and Teams transcription capture everything said. AI summaries extract requirements and actions. BA focuses on facilitation rather than simultaneous note-taking.","competency":"ba:ai-analysis"},{"q":"What remains distinctly human in AI-augmented BA work?","opts":["Documentation only","Stakeholder relationship building, political judgment, organizational context, and validating requirements against real business impact","Only senior BA activities","All BA work can be automated"],"a":1,"exp":"AI can draft requirements; only humans can understand organizational politics, read the room, build trust with resistant stakeholders, and validate against unstated organizational constraints.","competency":"ba:ai-analysis"}]'::jsonb);

-- Module 2: 15 questions
SELECT pg_temp.fill_ba_exam(2, '[{"q":"What is BABOK?","opts":["Business Analysis Body of Knowledge — IIBA''s comprehensive guide to BA practices and knowledge areas","A project management framework","A BA software tool","A requirements template"],"a":0,"exp":"BABOK v3 provides the profession''s knowledge foundation: 6 knowledge areas, 50+ techniques, and the competency framework for professional BAs.","competency":"ba:requirements"},{"q":"What are the 6 BABOK Knowledge Areas?","opts":["Scope, Schedule, Cost, Quality, Risk, Communication","BA Planning & Monitoring, Elicitation & Collaboration, Requirements Life Cycle, Strategy Analysis, Requirements Analysis, Solution Evaluation","Initiation, Planning, Execution, Control, Closure","Plan, Elicit, Analyze, Design, Test, Deploy"],"a":1,"exp":"BABOK''s 6 KAs cover the full BA lifecycle: planning how to do BA work, gathering requirements, managing them, understanding strategy, analyzing them, and evaluating solutions.","competency":"ba:requirements"},{"q":"What is CBAP certification?","opts":["An agile certification","A project management certification","A coding certification","Certified Business Analysis Professional — IIBA''s premier certification requiring 7,500 hours of BA experience"],"a":3,"exp":"CBAP requires 7,500 hours of BA experience in 10 years, references, and a 3.5-hour exam. It''s the most recognized BA certification globally.","competency":"ba:requirements"},{"q":"What is the difference between CBAP and PMI-PBA?","opts":["CBAP: IIBA''s certification, broad BA focus; PMI-PBA: PMI''s certification, emphasizes BA within project management context","Same certification","CBAP is only for IT","PMI-PBA is more advanced"],"a":0,"exp":"CBAP covers all BA contexts broadly. PMI-PBA focuses on BA within projects, aligning with PMI''s project management framework. Choose based on your organizational context.","competency":"ba:requirements"},{"q":"What is Strategy Analysis in BABOK?","opts":["Understanding the business context, identifying the need for change, and defining the solution approach","Competitive business strategy","Technology strategy","Financial analysis"],"a":0,"exp":"Strategy Analysis answers: Why are we doing this? What problem are we solving? What does success look like? Without strategy context, requirements are built for the wrong purpose.","competency":"ba:requirements"},{"q":"What is a plan-driven BA approach?","opts":["An agile approach with plans","A PM tool","Creating detailed project plans","A formal approach defining all requirements upfront — appropriate for stable requirements and regulated environments"],"a":3,"exp":"Plan-driven: detailed requirements documented before development begins. Appropriate for: fixed-price contracts, regulated industries, stable domains with predictable requirements.","competency":"ba:requirements"},{"q":"What is a change-driven BA approach?","opts":["Changing requirements frequently","A risk management technique","An iterative approach where requirements evolve through collaboration — appropriate for dynamic, uncertain domains","A change management framework"],"a":2,"exp":"Change-driven (Agile BA): requirements emerge through conversations and feedback. User stories replace detailed specifications. Embraces requirement evolution as learning.","competency":"ba:requirements"},{"q":"What is requirement traceability?","opts":["A JIRA feature","Version control for requirements","Tracking who wrote requirements","Linking requirements to their source (business need) and forward to design, test cases, and implementation"],"a":3,"exp":"Traceability answers: Why does this requirement exist? What does it trace to in the design? Which test cases verify it? Is it covered by implementation? Critical for regulated industries.","competency":"ba:requirements"},{"q":"Why is stakeholder analysis the first step in BA planning?","opts":["To assign responsibilities","Knowing who has interests in the solution determines who to involve, when, and how — missed stakeholders cause late requirements changes","For political reasons only","For project reporting purposes"],"a":1,"exp":"Stakeholders missed during analysis appear during review or after deployment with new requirements. Early comprehensive identification prevents expensive late changes.","competency":"ba:requirements"},{"q":"What is a RACI matrix in BA context?","opts":["Responsible, Accountable, Consulted, Informed — defines who does what for each BA activity and decision","A requirements template","A risk assessment tool","A project planning tool"],"a":0,"exp":"RACI clarifies roles: who is Responsible (does the work), Accountable (owns the outcome), Consulted (provides input), and Informed (receives updates) for requirements activities.","competency":"ba:requirements"},{"q":"Who is PMI-PBA best suited for?","opts":["IT professionals transitioning to BA","Only senior BAs","All business analysts","PMP holders or project-oriented BAs who want to formalize BA skills within a project management context"],"a":3,"exp":"PMI-PBA bridges PM and BA: it''s PM-centric in its approach. PMP holders add BA dimension. BAs in project environments benefit from the PM alignment.","competency":"ba:requirements"},{"q":"What are the PMI-PBA experience requirements?","opts":["Same as CBAP","5 years any experience","No experience required","4,500 hours BA experience (with degree) or 7,500 hours (without), plus 35 hours BA education"],"a":3,"exp":"PMI-PBA experience requirements are lower than CBAP. 4,500 hours is about 2-3 years of focused BA work — accessible earlier in career than CBAP''s 7,500 hours.","competency":"ba:requirements"},{"q":"What does PMI-PBA emphasize that CBAP de-emphasizes?","opts":["Data analysis","Process modeling","Requirements within project management lifecycle — integration of BA activities with project phases, deliverables, and governance","Agile techniques only"],"a":2,"exp":"PMI-PBA aligns BA to project phases: initiating, planning, executing, monitoring. Strong PMBOK alignment — for BAs working in project-structured organizations.","competency":"ba:requirements"},{"q":"What is the PMI-PBA exam format?","opts":["A practical BA exercise","Multiple choice only","50 questions, 2 hours","200 multiple choice questions in 4 hours — scenario-based, application-level"],"a":3,"exp":"PMI-PBA: 200 questions, 4 hours (0.2 min per question — fast pace). Scenarios test application of BA concepts in project contexts. Practice with timed conditions.","competency":"ba:requirements"},{"q":"What is the benefit of holding both PMP and PMI-PBA?","opts":["Required for BA roles","Only useful for consultants","No additional benefit","Demonstrates mastery of both delivery (PMP) and requirements (PMI-PBA) — the complete project leadership skill set"],"a":3,"exp":"PMP + PMI-PBA combination: commands premium for senior PM/BA hybrid roles. Demonstrates you can lead delivery AND define what gets delivered. Increasingly valued in Agile organizations.","competency":"ba:requirements"}]'::jsonb);

-- Module 3: 20 questions
SELECT pg_temp.fill_ba_exam(3, '[{"q":"How do you handle a resistant stakeholder?","opts":["Escalate immediately to management","Work around them","Exclude them from requirements","Understand their concerns, address them directly, involve them early, and find common ground with their interests"],"a":3,"exp":"Resistant stakeholders are often right about something. Understand why they''re resistant: fear of change, previous bad projects, concerns about their role. Address the real concern.","competency":"ba:stakeholders"},{"q":"What is a Power/Interest grid?","opts":["A project governance tool","A salary structure","A performance management tool","A 2x2 matrix mapping stakeholders by power (influence) and interest — guides engagement strategy for each quadrant"],"a":3,"exp":"High power/high interest: manage closely. High power/low interest: keep satisfied. Low power/high interest: keep informed. Low power/low interest: monitor.","competency":"ba:stakeholders"},{"q":"How do you manage conflicting stakeholder requirements?","opts":["Facilitate structured negotiation, identify underlying interests, find compromise, escalate only when necessary","Remove conflicting requirements","Accept all requirements","Choose the most senior stakeholder''s view"],"a":0,"exp":"Conflicts often reflect legitimate competing priorities. Facilitate: understand each stakeholder''s underlying need, find options that satisfy both, document the decision and rationale.","competency":"ba:stakeholders"},{"q":"What is requirements confirmation?","opts":["A final requirements review","Reviewing captured requirements with stakeholders to verify accuracy and completeness before further analysis","Legal approval of requirements","Getting sign-off on requirements"],"a":1,"exp":"Requirements confirmation closes the loop: ''Here''s what I heard you say — is this correct?'' Catches misunderstandings early, builds stakeholder trust, and prevents late surprises.","competency":"ba:stakeholders"},{"q":"What is stakeholder onboarding in BA?","opts":["A project kickoff activity","Bringing new stakeholders up to speed on project context, BA process, and expectations — preventing confusion and conflict","Only for senior stakeholders","HR onboarding"],"a":1,"exp":"Late-joining stakeholders can derail projects with ''Why aren''t we doing X?'' Proper onboarding: share context, decisions made, and reasoning — turning potential disruptors into contributors.","competency":"ba:stakeholders"},{"q":"Why do BAs need change management skills?","opts":["Change management is HR''s job","A perfectly designed solution fails if users don''t adopt it — BAs must ensure organizational readiness for change","Only for large-scale projects","Change management is optional"],"a":1,"exp":"Solutions fail adoption for human reasons: resistance, lack of training, unclear communication. BAs who understand change management design solutions and transition plans that get adopted.","competency":"ba:stakeholders"},{"q":"What is ADKAR?","opts":["A BA certification","A change management model: Awareness, Desire, Knowledge, Ability, Reinforcement — individual change progression","A requirements technique","An agile framework"],"a":1,"exp":"ADKAR: People must be Aware of why change is needed, Desire to participate, have Knowledge of how to change, Ability to implement, and Reinforcement to sustain it. Missing any step kills adoption.","competency":"ba:stakeholders"},{"q":"What is organizational resistance to change?","opts":["Always irrational","Insubordination","A management problem only","Natural human response to uncertainty — BAs must understand its sources and address them through engagement, not just mandate"],"a":3,"exp":"Resistance has valid causes: fear of job loss, lack of trust in management, previous failed projects, loss of status. BAs who engage resistance rather than ignore it get better solutions.","competency":"ba:stakeholders"},{"q":"What is a change impact assessment?","opts":["A business case component","A project risk assessment","An analysis of how a proposed solution affects people, processes, systems, and organizational structures — informing transition planning","A stakeholder analysis"],"a":2,"exp":"Change impact: ''This solution eliminates manual verification in accounts payable (4 FTEs). Process changes for 15 staff. Training required for 200 users. 3 systems being replaced.''","competency":"ba:stakeholders"},{"q":"What is a business readiness assessment?","opts":["A technical readiness check","Evaluating if the organization is prepared for go-live: people trained, processes updated, support ready, stakeholders communicated","Checking if IT is ready","A project gate review"],"a":1,"exp":"Business readiness: ''Are users trained? Are SOPs updated? Is the support helpdesk ready? Have we communicated to all affected parties?'' Missing readiness = failed go-live.","competency":"ba:stakeholders"},{"q":"For a BA, the primary purpose of a steering committee is to:","opts":["Provide executive governance, decisions, and unblock escalations","Replace stakeholder interviews","Do the BA''s analysis","Approve the UI"],"a":0,"exp":"A steering committee supplies executive governance — decisions, prioritization, funding, escalation. The BA prepares decisions for it and uses it to unblock and align.","competency":"ba:stakeholders"},{"q":"Reporting status to executives, the BA should lead with:","opts":["Technical logs","Every task detail","The full backlog","Outcomes, risks, decisions needed, and asks — not low-level activity"],"a":3,"exp":"Executives need a concise, decision-oriented view (outcomes/risks/decisions), not activity dumps.","competency":"ba:stakeholders"},{"q":"An impediment beyond the team''s authority threatens the timeline. The BA should:","opts":["Solve it without authority","Hide it to avoid alarm","Escalate with a clear problem, impact, options, and recommendation to the sponsor/steering committee","Wait and hope it resolves"],"a":2,"exp":"Effective escalation is structured (problem/impact/options/recommendation) and directed to the authority that can act.","competency":"ba:stakeholders"},{"q":"Two senior stakeholders publicly agree but consistently undermine the initiative. The best approach is:","opts":["Ignore it","Proceed regardless","Surface the underlying concerns privately, understand the real interests, and address them with the sponsor","Escalate publicly to embarrass them"],"a":2,"exp":"Misalignment behind public agreement signals unaddressed interests; the senior BA surfaces them privately and works the sponsor, not public confrontation.","competency":"ba:stakeholders"},{"q":"Two departments have conflicting priorities for the same system. The BA should:","opts":["Make the conflict explicit with shared criteria and facilitate a decision at the right authority level","Build both fully","Let them fight it out","Pick one arbitrarily"],"a":0,"exp":"Surface the conflict transparently, apply shared prioritization criteria, and route the decision to the authority who can make it.","competency":"ba:stakeholders"},{"q":"Resistance is strongest among middle managers. A likely root cause to investigate is:","opts":["They dislike technology","They are incompetent","Perceived loss of control, status, or unclear new roles under the change","Random preference"],"a":2,"exp":"Resistance usually stems from perceived loss (control/status/role clarity), not technophobia. Diagnose the real driver to design adoption.","competency":"ba:stakeholders"},{"q":"In a scope negotiation, the BA''s strongest position is grounded in:","opts":["Value, outcomes, constraints, and trade-offs tied to objectives","Whoever is loudest","Personal opinion","Vendor preference"],"a":0,"exp":"Negotiating from value/outcomes/constraints/trade-offs keeps decisions defensible and aligned to objectives.","competency":"ba:stakeholders"},{"q":"When two sponsors both demand \"top priority,\" the BA''s most effective tool is:","opts":["Doing both at half speed","A coin flip","Whoever is more senior wins automatically","A transparent, outcome-based prioritization framework decided by a shared authority"],"a":3,"exp":"An outcome-based framework plus the right deciding authority resolves competing \"top priorities\" defensibly.","competency":"ba:stakeholders"},{"q":"Building enterprise consensus for a transformation, the most durable approach is:","opts":["Get a one-time sign-off email","Mandate it top-down only","Avoid the dissenters","Co-create the solution with stakeholders for ownership, and align on shared outcomes"],"a":3,"exp":"Durable consensus comes from co-creation and shared-outcome alignment that builds ownership; mandates and avoided dissent produce fragile agreement.","competency":"ba:stakeholders"},{"q":"An active executive sponsor matters most because they:","opts":["Attend demos","Provide authority, remove cross-org barriers, and visibly champion the change","Test the software","Write the requirements"],"a":1,"exp":"A strong sponsor supplies authority, unblocks cross-organizational barriers, and visibly champions adoption — the biggest predictor of transformation success.","competency":"ba:stakeholders"}]'::jsonb);

-- Module 4: 20 questions
SELECT pg_temp.fill_ba_exam(4, '[{"q":"When is observation the best elicitation technique?","opts":["For all requirements","When interviews fail","When stakeholders struggle to articulate their process — watching them work reveals requirements they can''t describe","When stakeholders are unavailable"],"a":2,"exp":"People do their jobs automatically — they can''t always describe what they do. Observation captures the real process, not the idealized description stakeholders give in interviews.","competency":"ba:elicitation"},{"q":"What is the advantage of prototyping over written requirements?","opts":["Prototypes are cheaper","Written requirements are less accurate","Stakeholders can react to and evaluate something tangible — ''show me'' elicits better feedback than ''describe it''","Prototypes are faster to build"],"a":2,"exp":"Stakeholders often don''t know what they want until they see what they don''t want. Prototypes trigger concrete feedback: ''Not quite — I need this button here'' vs ''it should be user-friendly.''","competency":"ba:elicitation"},{"q":"What is a joint application development (JAD) session?","opts":["A structured workshop bringing business and IT together to jointly define requirements — high participation, faster consensus","A software development methodology","A project kickoff meeting","A code review session"],"a":0,"exp":"JAD sessions accelerate requirements through direct collaboration. Business experts and developers working together eliminates the misunderstanding that occurs when requirements pass through intermediaries.","competency":"ba:elicitation"},{"q":"When should surveys be used for elicitation?","opts":["When you need quantitative data from many stakeholders simultaneously — prioritization, preference data, usage patterns","As a replacement for interviews","For detailed requirements gathering","Only for customer research"],"a":0,"exp":"Surveys excel at scale: 500 users can''t be interviewed, but they can complete a survey. Use for: feature prioritization, process pain point ranking, and demographic data collection.","competency":"ba:elicitation"},{"q":"What is document analysis in elicitation?","opts":["A type of requirements validation","Reviewing the BA''s documentation","Examining existing business documents (current processes, reports, regulations) to extract requirements and understand the current state","Legal document review"],"a":2,"exp":"Document analysis: review existing reports, process documents, regulations, competitor products. Existing artifacts reveal requirements without stakeholder interviews — especially for replacement systems.","competency":"ba:elicitation"},{"q":"What is a customer journey map?","opts":["A website navigation diagram","A visual representation of a customer''s end-to-end experience across all touchpoints with an organization","A user story map","A process flow diagram"],"a":1,"exp":"Journey maps capture: customer actions, emotions, pain points, and opportunities across touchpoints. They reveal requirements that individual system-focused analysis misses.","competency":"ba:elicitation"},{"q":"What are AI/ML-specific requirements a BA must capture?","opts":["Training data requirements, model accuracy thresholds, explainability needs, bias considerations, fallback behavior","Just functional requirements","Performance requirements only","API integration requirements"],"a":0,"exp":"AI requirements differ from traditional system requirements. ''The fraud model must achieve 95% precision with <2% false positives, provide explainable decisions for regulatory compliance.''","competency":"ba:elicitation"},{"q":"What is an accessibility requirement?","opts":["Requirements ensuring the system is usable by people with disabilities — WCAG compliance, screen reader support, keyboard navigation","A legal compliance item only","A security requirement","A performance standard"],"a":0,"exp":"Accessibility requirements: ''The system shall comply with WCAG 2.1 AA standards, support screen readers (NVDA, JAWS), and be fully operable by keyboard without mouse.'' Legal requirement in many jurisdictions.","competency":"ba:elicitation"},{"q":"What is an API requirement?","opts":["Requirements defining interfaces between systems — data format, authentication, rate limits, error handling, versioning","A developer responsibility","A technical specification","A performance test"],"a":0,"exp":"BAs define API requirements from a business perspective: ''The payment API must process a transaction in <500ms, return a transaction ID, and support refund operations within 30 days.''","competency":"ba:elicitation"},{"q":"What is a data requirement in business analysis?","opts":["Database design","Technical data architecture","A developer responsibility only","Requirements defining what data must be captured, stored, quality standards, retention, and access controls"],"a":3,"exp":"Data requirements: ''The system shall capture customer consent at point of collection, store PII encrypted, retain for 7 years per regulation, and provide export within 30 days of request.''","competency":"ba:elicitation"},{"q":"A JTBD interview focuses on:","opts":["Demographics and segments","The customer''s timeline and context of struggle when they \"hired\" a solution","Pricing sensitivity only","Feature wishlists"],"a":1,"exp":"JTBD interviewing reconstructs the actual timeline/context of the struggle and the progress sought — surfacing the real job, not feature requests.","competency":"ba:elicitation"},{"q":"Contextual inquiry means:","opts":["Surveying users remotely","Observing and interviewing users in their real environment while they perform tasks","Reading the documentation","Running a focus group"],"a":1,"exp":"Contextual inquiry observes and questions users in their actual environment doing real work — revealing tacit needs and workarounds surveys miss.","competency":"ba:elicitation"},{"q":"Observing what users do is often more reliable than asking because:","opts":["People''s described behavior differs from actual behavior (forgotten steps, workarounds)","Observation needs no skill","It avoids stakeholders","It''s simply faster"],"a":0,"exp":"Stated behavior diverges from actual — people omit steps and workarounds. Observation captures the real process and latent needs.","competency":"ba:elicitation"},{"q":"Deep ethnographic research is most warranted when:","opts":["A survey already answered everything","Requirements are already well understood","The problem space is poorly understood and shaped by culture, context, and unspoken practice","Time is extremely short"],"a":2,"exp":"Ethnographic immersion pays off where the domain is poorly understood and shaped by tacit context/culture — reaching needs other methods can''t.","competency":"ba:elicitation"},{"q":"A stakeholder requests \"add more reports.\" The elite elicitation move is:","opts":["Build it immediately","Probe for the underlying decision/problem the reports would serve (e.g., 5 Whys)","Reject it outright","Document the feature as stated"],"a":1,"exp":"Requests are often solutions in disguise; eliciting the underlying problem/decision reveals the real need and often a better solution.","competency":"ba:elicitation"},{"q":"Across 15 interviews, one vivid story stands out emotionally. The skilled analyst:","opts":["Discards all stories","Builds for that one user","Weighs it against patterns across interviews to separate signal from a memorable anecdote","Treats it as the main requirement"],"a":2,"exp":"Vivid anecdotes bias judgment; signal detection weighs recurring evidence across sources to tell a true pattern from a one-off.","competency":"ba:elicitation"},{"q":"Interviewing a time-constrained executive, the BA should:","opts":["Ask a long list of detailed questions","Send a survey instead","Prepare focused, high-value questions on strategy, outcomes, constraints, and decision criteria","Improvise on the spot"],"a":2,"exp":"Executive interviews must be tightly prepared and high-leverage — strategy, outcomes, constraints, decision criteria — respecting limited time.","competency":"ba:elicitation"},{"q":"A guarded, skeptical stakeholder gives short, unhelpful answers. The best technique is:","opts":["Build rapport and safety, start from their perspective/pain, and use open, story-based questions","End the interview","Push harder with rapid-fire questions","Escalate immediately"],"a":0,"exp":"With guarded stakeholders, rapport/safety plus open, story-based questions from their world lowers defenses; pressure shuts it down.","competency":"ba:elicitation"},{"q":"The core risk of documenting requirements exactly as stakeholders state them is:","opts":["Too much detail","Capturing solutions and symptoms rather than the underlying needs","Slower delivery","Nothing — verbatim is safest"],"a":1,"exp":"Verbatim capture often records solutions/symptoms, not needs; elicitation must dig beneath stated requests to the underlying problem and value.","competency":"ba:elicitation"},{"q":"\"Go and see\" (genchi genbutsu) in elicitation means:","opts":["Ask only managers","Go to where the work happens and observe it directly","Rely on system logs","Read reports about the work"],"a":1,"exp":"Going to the actual place of work yields firsthand evidence of the real process and problems — stronger than secondhand reports.","competency":"ba:elicitation"}]'::jsonb);

-- Module 5: 20 questions
SELECT pg_temp.fill_ba_exam(5, '[{"q":"What is systems thinking in business analysis?","opts":["Understanding how components of a system interact — changes in one area have ripple effects on others","A documentation approach","Knowledge of IT systems","A modeling technique"],"a":0,"exp":"Systems thinking prevents the ''narrow requirements'' problem: a requirement that''s correct in isolation but breaks something elsewhere in the system.","competency":"ba:facilitation"},{"q":"What is the difference between active listening and passive listening?","opts":["Passive listening is more respectful","No real difference","Active listening requires note-taking","Active listening: paraphrasing, asking clarifying questions, confirming understanding. Passive: just hearing words without engagement."],"a":3,"exp":"BAs who passively listen miss nuance: what''s NOT said, emotional cues, and real concerns behind polished stakeholder statements. Active listening uncovers requirements passive listening misses.","competency":"ba:facilitation"},{"q":"What is domain knowledge in BA?","opts":["IT system knowledge only","Project management knowledge","Deep understanding of the business area being analyzed — processes, terminology, regulations, and typical challenges","Knowledge of BA tools"],"a":2,"exp":"Domain knowledge accelerates elicitation: you ask better questions, recognize when requirements don''t make sense, and speak the stakeholder''s language. Build it through industry experience and research.","competency":"ba:facilitation"},{"q":"What is facilitation in business analysis?","opts":["Guiding groups through structured processes to achieve desired outcomes — elicitation workshops, design sessions, conflict resolution","Presenting to stakeholders","Scheduling meetings","Writing meeting minutes"],"a":0,"exp":"Facilitation is directing group energy toward outcomes. A skilled BA facilitator elicits more requirements in a 2-hour workshop than a month of one-on-one interviews.","competency":"ba:facilitation"},{"q":"What is critical thinking in business analysis?","opts":["Only for senior BAs","A personality trait","Objectively analyzing information, questioning assumptions, and evaluating evidence before accepting requirements as valid","Criticizing stakeholder ideas"],"a":2,"exp":"Critical thinking prevents ''requirements laundering'' — accepting stakeholder requests at face value without questioning if they solve the real problem or create new ones.","competency":"ba:facilitation"},{"q":"How should a BA communicate with executives vs end users?","opts":["Keep all communication brief","Same communication for all","Executives: outcomes, costs, risks, and strategic alignment. End users: practical impact, how it helps them, what will change for them","Technical detail for everyone"],"a":2,"exp":"Executives need: ''This solution delivers $2M annual savings with 4-month payback at moderate risk.'' End users need: ''This will eliminate the manual data re-entry you do 15 times per day.''","competency":"ba:facilitation"},{"q":"What is the pyramid principle for BA communication?","opts":["Lead with the conclusion/recommendation, then provide supporting evidence — don''t make audiences wait for the point","A hierarchical diagram","An executive presentation template","A documentation structure"],"a":0,"exp":"Pyramid structure: ''We recommend Solution B.'' Why? ''It costs 40% less, delivers faster, and reduces technical risk.'' Evidence for each. Executives get the answer first, detail if needed.","competency":"ba:facilitation"},{"q":"What makes BA documentation effective?","opts":["Long and comprehensive documents","Clear purpose, right level of detail for the audience, correct structure, and visual elements to aid comprehension","Minimal documentation","More detail is always better"],"a":1,"exp":"Effective BA documentation: explains the ''so what,'' uses the reader''s vocabulary, includes diagrams for complex concepts, and is maintained when requirements change.","competency":"ba:facilitation"},{"q":"What is active facilitation in requirements workshops?","opts":["Presenting requirements to stakeholders","Recording meeting notes","Asking prepared questions only","Guiding group discussion toward conclusions: managing participation, resolving conflicts, keeping focus, building consensus"],"a":3,"exp":"Active facilitation: draw out quiet participants, respectfully challenge dominant voices, redirect tangents, surface hidden disagreements, and guide toward concrete outcomes and decisions.","competency":"ba:facilitation"},{"q":"What is a BA''s role when presenting requirements to a review board?","opts":["Delegating to the PM","Technical presentation only","Concisely presenting the requirements approach, key decisions made, open issues, and seeking input and approval","Reading requirements documents aloud"],"a":2,"exp":"Requirements review presentation: ''Here''s the approach taken, key requirements decisions, risks identified, open questions requiring your input, and the sign-off being requested.''","competency":"ba:facilitation"},{"q":"The facilitator''s primary job in a discovery workshop is to:","opts":["Take notes silently","Decide the outcome alone","Create structure and safety so the group surfaces and converges on insights","Dominate with their own ideas"],"a":2,"exp":"Facilitation provides structure and psychological safety so the group produces and converges on insight — guiding process, not owning content.","competency":"ba:facilitation"},{"q":"Event Storming is most useful for:","opts":["Collaboratively mapping a business process/domain as a series of events with stakeholders","Designing the UI","Writing the BRD alone","Estimating budgets"],"a":0,"exp":"Event Storming gathers stakeholders to map domain events/flows on a wall — fast shared understanding of complex processes and boundaries.","competency":"ba:facilitation"},{"q":"A user story map is organized to:","opts":["Rank developers","List bugs","Replace the backlog index","Show the user journey across the top with prioritized slices beneath, revealing scope and releases"],"a":3,"exp":"Story mapping arranges activities along the journey with prioritized detail beneath — exposing scope, gaps, and coherent release slices.","competency":"ba:facilitation"},{"q":"Impact mapping connects:","opts":["Tasks to dates","Goal → actors → impacts → deliverables, keeping work tied to outcomes","Servers to databases","People to salaries"],"a":1,"exp":"Impact mapping links goal → actors → impacts (behavior changes) → deliverables, anchoring scope to outcomes and exposing assumptions.","competency":"ba:facilitation"},{"q":"In a prioritization workshop, the facilitator''s key contribution is:","opts":["Avoiding a decision","Providing shared, transparent criteria/method so the group decides defensibly","Choosing the priorities themselves","Letting the loudest voice win"],"a":1,"exp":"The facilitator supplies a shared method/criteria (value/effort, WSJF) so the group decides transparently — not deciding for them.","competency":"ba:facilitation"},{"q":"Facilitating two groups in open conflict, the strongest first move is:","opts":["Force an immediate vote","Establish shared goals and ground rules, then surface interests behind positions before seeking options","Take the more senior side","Cancel the session"],"a":1,"exp":"Move from positions to interests under shared goals, then generate options — interest-based facilitation resolves conflict more durably than forcing votes.","competency":"ba:facilitation"},{"q":"Facilitating an executive decision forum, the BA should:","opts":["Avoid making a recommendation","Present every detail","Let it run open-ended","Frame the decision, options, trade-offs, and a recommendation, and drive to a clear decision and owner"],"a":3,"exp":"Executives need a framed decision (options/trade-offs/recommendation) facilitated to a clear decision and owner, respecting their time.","competency":"ba:facilitation"},{"q":"A retrospective''s purpose is to:","opts":["Re-plan the backlog","Assign blame","Inspect how the team works and agree concrete improvements in a safe setting","Report status to managers"],"a":2,"exp":"A retrospective is a blameless inspect-and-adapt on the team''s process, producing a few concrete, owned improvements.","competency":"ba:facilitation"},{"q":"Facilitating alignment across 6 teams, the biggest added challenge vs one team is:","opts":["Managing dependencies, shared decisions, and consistent understanding across groups with divergent context","Nothing changes","Less preparation","Fewer people to manage"],"a":0,"exp":"Multi-team facilitation must handle cross-team dependencies, shared decisions, and aligning divergent contexts — more structure and prep than single-team.","competency":"ba:facilitation"},{"q":"Mid-workshop, discussion circles with no convergence. The facilitator should:","opts":["Decide unilaterally","Use a convergence technique (dot-voting, timeboxing, an agreed decision rule) to reach a decision","End the workshop","Let it continue indefinitely"],"a":1,"exp":"When stuck in divergence, apply a convergence technique to move the group to a decision — a core facilitation skill.","competency":"ba:facilitation"}]'::jsonb);

-- Module 6: 25 questions
SELECT pg_temp.fill_ba_exam(6, '[{"q":"What is the difference between a BRD and FRS?","opts":["BRD: business outcomes and needs; FRS: system functions that will fulfill those needs — BRD is ''why'', FRS is ''what''","FRS is for developers only","Same document, different names","BRD is for management only"],"a":0,"exp":"BRD: ''We need to reduce customer wait time by 50%.'' FRS: ''The system shall display estimated wait time. The system shall send SMS notifications.'' BRD drives FRS.","competency":"ba:requirements"},{"q":"What makes a good acceptance criterion?","opts":["Long and detailed description","Testable, specific, and unambiguous — can be verified as pass/fail by anyone reading it","Approved by management","Written by the developer"],"a":1,"exp":"Good AC: ''When a user submits a form with an invalid email, the system displays an error message within 1 second.'' Bad AC: ''The system should validate user input properly.''","competency":"ba:requirements"},{"q":"What is a use case?","opts":["A test case","A business scenario","A user story format","A description of system behavior in response to a user action — actor, trigger, main flow, alternative flows, exceptions"],"a":3,"exp":"Use cases describe system-actor interactions: Customer places order → System validates inventory → System processes payment → System confirms order. More detailed than user stories.","competency":"ba:requirements"},{"q":"What is the INVEST criteria for user stories?","opts":["An agile planning tool","Independent, Negotiable, Valuable, Estimable, Small, Testable — criteria for well-formed user stories","A user story quality metric","A prioritization framework"],"a":1,"exp":"INVEST guides user story quality: Independent (can deploy alone), Negotiable (details TBD), Valuable (business value clear), Estimable, Small (fits in a sprint), Testable.","competency":"ba:requirements"},{"q":"When should you use use cases vs user stories?","opts":["User stories are always better","They''re interchangeable","Use cases: complex, formal documentation for regulated industries or detailed system specs; user stories: collaborative, conversational, for agile delivery","Use cases are outdated"],"a":2,"exp":"Use cases suit: complex business rules, multiple alternative flows, regulated systems needing formal documentation. User stories suit: agile teams preferring conversation over specification.","competency":"ba:requirements"},{"q":"What is a requirement ''smell''?","opts":["A warning sign of poor quality: vague terms like ''user-friendly'', ''efficient'', ''flexible'' that can''t be objectively verified","A bad requirement smell","A code review term","A BA technique"],"a":0,"exp":"Vague requirements create rework: ''The system shall be user-friendly'' — what does that mean? Every developer has a different interpretation. Make it measurable: ''Users shall complete checkout in < 3 minutes.''","competency":"ba:requirements"},{"q":"What is gold-plating in requirements?","opts":["Adding too much detail","A quality issue","Over-documenting requirements","Adding features beyond what the business needs — scope creep driven by BAs, developers, or stakeholders with good intentions"],"a":3,"exp":"Gold-plating delivers unrequested features: developers adding cool functions, BAs over-specifying. Every added feature costs time and money without corresponding business value.","competency":"ba:requirements"},{"q":"What is a requirements walkthrough?","opts":["A structured peer review where the author presents requirements to colleagues who identify defects","A training activity","A physical tour","A stakeholder presentation"],"a":0,"exp":"Walkthroughs catch defects before they reach development: missing scenarios, contradictions, ambiguous terms, and feasibility issues. One hour in review saves days in rework.","competency":"ba:requirements"},{"q":"What does ''testable'' mean for a requirement?","opts":["The requirement can be verified as pass/fail through a defined test — anyone running the test gets the same result","Requirements that QA reviews","A developer can test it","Automated test coverage"],"a":0,"exp":"Testable: ''The system shall display search results within 2 seconds for 95% of queries.'' Not testable: ''The system shall respond quickly.'' Testability forces precision.","competency":"ba:requirements"},{"q":"What is requirement ambiguity?","opts":["A vague business need","An unclear stakeholder request","A requirement that can be interpreted in multiple ways by different readers — the most dangerous quality defect","A complex requirement"],"a":2,"exp":"Ambiguous requirements are interpreted differently by BAs, developers, and testers. Each builds their own version. Integration reveals the inconsistencies — expensively.","competency":"ba:requirements"},{"q":"What is an actor in a use case?","opts":["A software component","A system user only","A stakeholder type","A role that interacts with the system — primary actors initiate use cases, secondary actors support them"],"a":3,"exp":"Actors represent roles: Customer (primary actor), Payment Gateway (secondary actor/system). The same person may play multiple roles — a customer who is also an admin.","competency":"ba:requirements"},{"q":"What is the main success scenario in a use case?","opts":["The most common scenario","The primary flow where everything goes right — the ''happy path'' from trigger to successful completion","The most important scenario","The only required scenario"],"a":1,"exp":"The main success scenario: customer selects product → adds to cart → enters payment → order confirmed. Alternative flows handle: out of stock, payment declined, customer cancelled.","competency":"ba:requirements"},{"q":"What is the include relationship in use case diagrams?","opts":["An optional relationship","One use case always includes another — extract common behavior shared by multiple use cases","A use case dependency","One use case including another actor"],"a":1,"exp":"Include: ''Place Order'' includes ''Verify Payment.'' Every time you place an order, payment is always verified. Extract shared behavior into included use cases to avoid duplication.","competency":"ba:requirements"},{"q":"What is the extend relationship in use case diagrams?","opts":["An always-executed relationship","A required relationship","A system dependency","A conditional extension — one use case sometimes extends another with additional behavior under specific conditions"],"a":3,"exp":"Extend: ''Apply Discount'' extends ''Place Order'' when a coupon is entered. The extension is conditional and optional — ''Place Order'' is complete without it.","competency":"ba:requirements"},{"q":"What is use case scope?","opts":["The number of use cases","Project scope document","The system boundary — what the system does vs what external actors do — defined by the use case diagram boundary","A requirements boundary"],"a":2,"exp":"Use case scope defines what''s IN the system vs outside. Everything inside the system boundary is automated. Actors outside interact but are not automated. Scope disputes are resolved here.","competency":"ba:requirements"},{"q":"What is BDD (Behavior-Driven Development)?","opts":["A programming paradigm","A collaboration technique where BA, developer, and tester define system behavior using Given/When/Then scenarios before development","An agile methodology","A testing framework"],"a":1,"exp":"BDD creates shared understanding: Given [context], When [action], Then [outcome]. All three amigos agree on the behavior before a line of code is written.","competency":"ba:requirements"},{"q":"What is a Gherkin scenario?","opts":["A test case format","A human-readable BDD format: Given [precondition], When [action], Then [expected outcome] — executable as automated tests","A vegetable-inspired framework","A user story format"],"a":1,"exp":"Gherkin: ''Given a customer has items in their cart, When they apply a valid discount code, Then the total reflects the discount and an email confirmation is sent.''","competency":"ba:requirements"},{"q":"What is the Three Amigos meeting?","opts":["A sprint ceremony","A collaboration between BA (requirements), developer (implementation), and tester (validation) to align on behavior before development","A stakeholder review","A project management ceremony"],"a":1,"exp":"Three Amigos prevents misalignment: BA clarifies intent, developer identifies technical constraints, tester identifies missing scenarios. All agree before development starts.","competency":"ba:requirements"},{"q":"What is specification by example?","opts":["An API documentation technique","Using concrete examples to illustrate requirements rather than abstract rules — examples become automated acceptance tests","A requirements template","Giving development examples"],"a":1,"exp":"Abstract: ''The system shall validate dates.'' Concrete: ''Given Jan 31 and adding 1 month, the result is Feb 28 (not Feb 31).'' Examples catch edge cases abstract rules miss.","competency":"ba:requirements"},{"q":"What is the benefit of defining acceptance tests before development?","opts":["Tests are more accurate","Creates shared understanding of requirements, prevents gold-plating, and provides objective completion criteria","Reduces testing time only","Developers prefer this"],"a":1,"exp":"Pre-defined acceptance tests: developer knows exactly what ''done'' means, BA can validate without ambiguity, tester has test cases ready. Eliminates ''I thought it meant...'' arguments.","competency":"ba:requirements"},{"q":"What are the CBAP experience requirements?","opts":["5 years any IT experience","CBAP has no experience requirements","3 years BA experience","7,500 hours of BA work experience in the last 10 years, with 900 hours in at least 4 of 6 BABOK Knowledge Areas"],"a":3,"exp":"CBAP requires substantial BA experience. The application requires detailed documentation of BA work mapped to BABOK KAs. A professional reference validates the experience.","competency":"ba:requirements"},{"q":"What level of thinking do CBAP exam questions test?","opts":["Memorization of BABOK","Technical knowledge","Knowledge and recall","Application and analysis — applying BABOK concepts to complex, realistic scenarios with multiple defensible answers"],"a":3,"exp":"CBAP is not a memorization test. Questions present complex BA scenarios with 4 plausible answers. Understanding BABOK well enough to apply it in novel situations is required.","competency":"ba:requirements"},{"q":"What is the best CBAP study strategy?","opts":["Deep BABOK v3 understanding + Ecba/CCBA experience building + 500+ practice questions + study group","Take a one-week boot camp only","Study other BA books without BABOK","Read BABOK once"],"a":0,"exp":"CBAP study: BABOK v3 mastery (not memorization), extensive scenario practice with rationale understanding, study group for discussion, and experience reflection against BABOK concepts.","competency":"ba:requirements"},{"q":"What distinguishes a CBAP question from a simpler BA exam?","opts":["Complex scenarios with competing priorities, multiple stakeholder perspectives, and no obvious single correct answer — requires judgment","More technical content","Longer questions","More BABOK recall"],"a":0,"exp":"CBAP scenarios: stakeholder conflict, competing requirements, ethical dilemmas, organizational constraints. Choose the BABOK-aligned best answer given the specific context — not the generically correct answer.","competency":"ba:requirements"},{"q":"What are CDUs in CBAP recertification?","opts":["Competency Development Updates","Certification Delivery Units","Continuing Development Units","Continuing Development Units — professional development hours earned through training, conferences, volunteering, and writing to maintain CBAP"],"a":2,"exp":"CBAP requires 60 CDUs every 3 years to maintain certification. Earned through: IIBA events, training, writing articles, mentoring, and chapter involvement.","competency":"ba:requirements"}]'::jsonb);

-- Module 7: 20 questions
SELECT pg_temp.fill_ba_exam(7, '[{"q":"What is BPMN?","opts":["A project management method","A programming language","A database modeling language","Business Process Model and Notation — the international standard for visualizing business processes"],"a":3,"exp":"BPMN provides a common language for process communication: business stakeholders and technical teams read the same diagrams. Tools: Signavio, Lucidchart, Visio, draw.io.","competency":"ba:process-analysis"},{"q":"What is an exclusive gateway in BPMN?","opts":["An event trigger","A security checkpoint","A decision point where exactly one outgoing path is taken based on a condition — like an if/else statement","A parallel process start"],"a":2,"exp":"Exclusive (XOR) gateway: ''Is credit approved? Yes → process order. No → notify customer.'' Only one path executes. Contrast with inclusive (OR) and parallel (AND) gateways.","competency":"ba:process-analysis"},{"q":"What is the difference between AS-IS and TO-BE process models?","opts":["AS-IS: current state process documentation; TO-BE: future desired state after improvement — gap between them defines requirements","TO-BE is the only model needed","Same model, different time","AS-IS is more important"],"a":0,"exp":"AS-IS reveals current pain points and inefficiencies. TO-BE defines the improved process. The gap between them becomes the change requirements for the project.","competency":"ba:process-analysis"},{"q":"What is a swimlane diagram?","opts":["A project timeline","A sports facility design","A BPMN element","A process diagram divided into horizontal or vertical lanes representing different roles, departments, or systems"],"a":3,"exp":"Swimlanes show who does what in a process: Customer lane, Sales lane, Warehouse lane. Immediately reveals handoffs, bottlenecks, and accountability gaps.","competency":"ba:process-analysis"},{"q":"What is a process trigger?","opts":["A starting condition","A gateway condition","A process exception","The event that initiates a business process — a customer order, a date/time, an exception, or a message from another system"],"a":3,"exp":"Process triggers: Customer submits order (message event), Monthly payroll run (timer event), Stock falls below threshold (condition event). Identifying triggers defines process scope.","competency":"ba:process-analysis"},{"q":"What is the Lean definition of waste?","opts":["Staff idle time","Any activity that consumes resources without adding value from the customer''s perspective — eliminate it","Excess inventory only","Any inefficiency"],"a":1,"exp":"Lean waste (MUDA): Transportation, Inventory, Motion, Waiting, Overproduction, Over-processing, Defects (TIMWOOD). BAs identify these in AS-IS processes to design better TO-BE.","competency":"ba:process-analysis"},{"q":"What is DMAIC?","opts":["A BA framework","A requirements approach","Six Sigma problem-solving methodology: Define, Measure, Analyze, Improve, Control","A project management method"],"a":2,"exp":"DMAIC structures process improvement: Define the problem → Measure current performance → Analyze root causes → Improve the process → Control to sustain improvements.","competency":"ba:process-analysis"},{"q":"What is value stream mapping?","opts":["Mapping organizational values","A financial analysis tool","A stakeholder map","A Lean tool visualizing the flow of materials and information from customer request to delivery — revealing waste and delays"],"a":3,"exp":"VSM shows the complete value delivery process with cycle times, wait times, and inventory levels. Reveals that most time is spent waiting, not working — typical 95% wait time.","competency":"ba:process-analysis"},{"q":"What is root cause analysis?","opts":["Systematically identifying the fundamental cause of a problem — not just symptoms — to prevent recurrence","A quality review","Finding who is to blame","A process audit"],"a":0,"exp":"Root cause analysis prevents band-aids on symptoms. Fix the symptom (approve more manually) vs fix the root cause (fix the system that generates the exceptions). Fishbone + 5 Whys.","competency":"ba:process-analysis"},{"q":"What is a process metric?","opts":["A project KPI","A financial measure","A BPMN element","A quantifiable measure of process performance: cycle time, throughput, error rate, cost per transaction"],"a":3,"exp":"Process metrics enable objective improvement measurement: ''Current: 4-day order processing cycle. Target: 1-day cycle. Achieved: 1.2-day cycle.'' Data-driven improvement.","competency":"ba:process-analysis"},{"q":"What is a Data Flow Diagram?","opts":["A database design tool","A network diagram","A process flow diagram","A diagram showing how data moves through a system: external entities, processes, data stores, and data flows"],"a":3,"exp":"DFDs focus on data, not sequence: what data enters the system, what transforms it, what stores it, and what data leaves. Context (Level 0), system (Level 1), detailed (Level 2).","competency":"ba:process-analysis"},{"q":"What is a conceptual data model?","opts":["A high-level representation of business entities and their relationships — business language, not technical database design","An ERD for developers","A data architecture document","A database schema"],"a":0,"exp":"Conceptual model: Customer places Orders, Order contains OrderItems, Product is an OrderItem. Business entities and relationships — communicates to business stakeholders, not DBAs.","competency":"ba:process-analysis"},{"q":"What is a business rule?","opts":["A company policy document","A constraint or guideline governing business operations: ''A customer must be 18+ to purchase alcohol'' — defines system behavior","A technical constraint","A legal requirement only"],"a":1,"exp":"Business rules drive requirements: ''Orders over $1000 require manager approval.'' ''Prescription drugs require verified prescription.'' Rules must be captured explicitly or they''ll be missed.","competency":"ba:process-analysis"},{"q":"What is cardinality in entity-relationship modeling?","opts":["A data quality metric","Entity size","A database term only","The number of instances in one entity that relate to instances in another: one-to-one, one-to-many, many-to-many"],"a":3,"exp":"Cardinality: one Customer has many Orders (1:M). One Order has many OrderItems (1:M). One Product appears in many OrderItems (M:M through OrderItem). Defines data relationship constraints.","competency":"ba:process-analysis"},{"q":"What is a data dictionary?","opts":["A centralized repository defining all data elements: name, definition, data type, valid values, and business rules","A technical specification","A general dictionary","A database index"],"a":0,"exp":"Data dictionaries prevent inconsistency: ''Customer'' means the same thing everywhere. ''Order Date'' is YYYY-MM-DD format. All teams use the same definition.","competency":"ba:process-analysis"},{"q":"What is a well-formed problem statement?","opts":["A stakeholder complaint","A clear articulation of the gap between current state and desired state — without prescribing a solution","A description of the desired solution","A project scope statement"],"a":1,"exp":"Good problem statement: ''Order processing takes 4 days, resulting in 23% customer cancellations. The business needs same-day processing to match competitor performance.'' No solution prescribed.","competency":"ba:process-analysis"},{"q":"Why should BAs avoid defining solutions too early?","opts":["Solutions change anyway","BAs never define solutions","Jumping to solutions without problem definition leads to building the right solution to the wrong problem","Solutions are the developer''s job"],"a":2,"exp":"The most common project failure: correctly building the wrong solution. Problem definition prevents this. ''Our website is slow'' → customers are actually abandoning due to poor UX, not speed.","competency":"ba:process-analysis"},{"q":"What is a fishbone diagram used for?","opts":["A BPMN alternative","Root cause analysis — visually categorizing potential causes of a problem across: People, Process, Technology, Materials, Environment","Process flow modeling","Problem statement creation"],"a":1,"exp":"Fishbone (Cause-and-Effect) diagram: the problem is the fish head, potential causes form the ''bones'' in categories. Facilitates group brainstorming of all possible causes.","competency":"ba:process-analysis"},{"q":"What is opportunity analysis?","opts":["A competitive analysis","Financial investment analysis","A market analysis technique","Identifying improvements, innovations, and new capabilities that could create value — not just solving existing problems"],"a":3,"exp":"BAs do more than fix problems: they identify opportunities. ''Competitors offer 1-click reorder — we could implement this for 15% revenue uplift.'' Proactive value creation.","competency":"ba:process-analysis"},{"q":"What is a current state assessment?","opts":["A thorough analysis of how things work today — processes, systems, data, organization — as the foundation for improvement","A project status report","A performance review","A system audit"],"a":0,"exp":"Current state assessment: map the AS-IS process, identify pain points, quantify performance gaps, understand root causes. You can''t design a good TO-BE without understanding the AS-IS.","competency":"ba:process-analysis"}]'::jsonb);

-- Module 8: 20 questions
SELECT pg_temp.fill_ba_exam(8, '[{"q":"What is the relationship between BA and Enterprise Architecture?","opts":["BA provides detailed requirements that EA translates into architectural standards — BA is the demand side, EA is the supply side","EA makes BA unnecessary","They work independently","BA replaces EA"],"a":0,"exp":"EA defines technology standards and architectural patterns. BA works within these guardrails and informs EA about emerging business needs. Misalignment creates technical debt.","competency":"ba:business-architecture"},{"q":"What is a business capability map?","opts":["A process map","An organizational chart","A model of what an organization can do — capabilities like ''order management,'' ''fraud detection'' — independent of how those capabilities are implemented","A skills matrix"],"a":2,"exp":"Capability maps are stable even when systems change: ''We have order management capability — currently in legacy system, moving to SaaS.'' Aligns BA requirements to long-term capability development.","competency":"ba:business-architecture"},{"q":"What is an application portfolio in EA context?","opts":["A vendor list","A project portfolio","A software catalog","The inventory of all applications in the organization, their business capabilities supported, and their lifecycle status"],"a":3,"exp":"Application portfolio: ''CRM supports customer management capability (strategic — invest). Order system is legacy (tolerate — replace). Reporting tool is redundant (eliminate).''","competency":"ba:business-architecture"},{"q":"What is the strategic alignment of BA work?","opts":["Ensuring BA projects and requirements support organizational strategy — not just solving immediate problems without strategic context","Following enterprise standards","Aligning to BA frameworks","Reporting to executives"],"a":0,"exp":"Strategic alignment: ''This CRM project supports our strategy of improving customer lifetime value. Requirements should focus on retention analytics and proactive service — not just ticket management.''","competency":"ba:business-architecture"},{"q":"What is IT governance in the context of BA?","opts":["IT department management","A compliance requirement","IT project oversight only","Decision rights and accountability frameworks ensuring IT investments align with business strategy and deliver value"],"a":3,"exp":"IT governance: who decides what gets built, how priorities are set, how performance is measured. BAs operate within governance structures: investment committees, architecture review boards.","competency":"ba:business-architecture"},{"q":"What is an operating model?","opts":["A business process model","An IT architecture model","A computer simulation","How an organization is structured to deliver its strategy: processes, capabilities, technology, people, and governance working together"],"a":3,"exp":"Operating model analysis: ''Current model has 7 approval layers for expenses over $500 — creating 3-day delay. TO-BE model: automated approval for <$5000 reduces to 2 hours.''","competency":"ba:business-architecture"},{"q":"What are organizational requirements in BA?","opts":["Changes to people, processes, skills, and structure required to operate the new solution — often missed in technical requirements","HR requirements","Requirements about the organization itself","Management requirements"],"a":0,"exp":"Organizational requirements: ''New system requires 2 new data analyst roles, restructured accounts payable process, and customer service training for 200 agents.'' Often the biggest implementation risk.","competency":"ba:business-architecture"},{"q":"What is a capability maturity assessment?","opts":["A technology assessment","A project quality review","Employee performance assessment","Evaluating an organization''s current capability level against a maturity model — identifying gaps and improvement priorities"],"a":3,"exp":"Capability maturity: ''Our data analytics capability is Level 1 (ad-hoc). Target is Level 3 (managed) within 2 years. Gap requires: data governance, analytics platform, trained staff.''","competency":"ba:business-architecture"},{"q":"What is an organizational impact analysis?","opts":["A project impact study","A risk assessment","A financial impact study","Assessing how a solution change affects organizational structure, roles, responsibilities, processes, and culture"],"a":3,"exp":"Org impact analysis: ''Solution automates 60% of processing clerk work → 4 of 7 positions eliminated, 3 redeployed to exception handling. New QA role required. Manager scope changes.''","competency":"ba:business-architecture"},{"q":"What is a target operating model?","opts":["A process improvement plan","A future technology architecture","A headcount plan","The future state of how the organization will operate — structure, processes, capabilities, technology — aligned to strategy"],"a":3,"exp":"TOM: ''By 2026, customer service operates with AI-assisted agents, self-service handling 70% of inquiries, humans handling complex cases only. Requires platform, training, and role redesign.''","competency":"ba:business-architecture"},{"q":"A business capability map answers which question?","opts":["What the current sprint backlog contains","Who reports to whom on the org chart","Which software vendors are under contract","What the business is able to do (its capabilities), independent of how or who"],"a":3,"exp":"A capability map describes WHAT a business can do (stable abilities like \"Customer Onboarding\"), decoupled from process, org structure, and tools — a stable backbone for analysis and transformation.","competency":"ba:business-architecture"},{"q":"A value stream is best described as:","opts":["The end-to-end sequence of activities that delivers value to a customer/stakeholder","An organization chart","A list of departments","A budget allocation"],"a":0,"exp":"A value stream is the end-to-end set of value-adding activities producing a result for a customer — cutting across functions, and the lens for finding cross-functional waste and improvement.","competency":"ba:business-architecture"},{"q":"An operating model defines:","opts":["The sprint cadence","The quarterly revenue target","The UI design system","How an organization combines people, process, technology, structure, and governance to deliver its strategy"],"a":3,"exp":"An operating model describes HOW the organization is configured to execute strategy — the bridge between strategy and execution.","competency":"ba:business-architecture"},{"q":"When recommending an org-design change to support a new operating model, the BA''s primary concern is:","opts":["Choosing the trendiest structure","Copying a competitor''s structure","Reducing headcount as much as possible","Aligning structure, roles, decision rights, and incentives to the target capabilities and value streams"],"a":3,"exp":"Org design must align structure, roles, decision rights, and incentives to the capabilities/value streams the strategy requires — not headcount-cutting, imitation, or fashion.","competency":"ba:business-architecture"},{"q":"A target-state (to-be) business architecture represents:","opts":["The desired future configuration of capabilities, processes, and structure that supports the strategy","The current state documented in detail","The IT network diagram","A list of current problems"],"a":0,"exp":"Target-state architecture defines the future configuration the organization is transforming toward — the destination a roadmap closes the gap to.","competency":"ba:business-architecture"},{"q":"A transformation roadmap is most credible when it is:","opts":["Organized purely by software releases","A list of features with no dependencies","A single big-bang cutover with no phases","Sequenced by capability gaps, dependencies, value, and risk into phased waves"],"a":3,"exp":"A defensible roadmap sequences the current→target gap into phased waves driven by capability gaps, dependencies, value delivery, and risk — not big-bang cutovers or release-only views.","competency":"ba:business-architecture"},{"q":"A capability heatmap is used to:","opts":["Visually highlight which capabilities are strong vs weak/at-risk, to focus investment","Track server temperature","Show the sprint burndown","Display the org-chart hierarchy"],"a":0,"exp":"A heatmap overlays maturity/performance/risk onto the capability map, directing transformation investment to the highest-need areas.","competency":"ba:business-architecture"},{"q":"An executive asks a BA to justify a transformation investment. The most strategically aligned justification traces the initiative to:","opts":["The newest technology trend","The number of features delivered","What a competitor announced","A specific strategic objective and the capability gap it closes, with the expected measurable outcome"],"a":3,"exp":"Strategic alignment links each initiative to a stated objective and the capability gap it closes, with the measurable outcome — the language executives fund, unlike trend/competitor/output rationales.","competency":"ba:business-architecture"},{"q":"Designing enterprise change for a new operating model, the BA must address:","opts":["Only the new org chart","People, process, technology, and governance changes together, plus stakeholder adoption and impact","Only the technology rollout","Only the training schedule"],"a":1,"exp":"Enterprise change is socio-technical: people, process, technology, and governance must change together, with deliberate adoption and impact management — a tech-only or org-only view fails.","competency":"ba:business-architecture"},{"q":"At the executive level, the strongest transformation plan a BA can present is one that:","opts":["Defers all decisions to the vendor","Connects strategy → target capabilities → phased roadmap → investment → measurable outcomes and risks","Lists every task in the program","Focuses on tooling decisions"],"a":1,"exp":"Executive transformation planning tells a coherent strategy-to-outcome story (strategy → capabilities → roadmap → investment → outcomes/risks) — the board-level narrative, not a task list or tooling focus.","competency":"ba:business-architecture"}]'::jsonb);

-- Module 9: 25 questions
SELECT pg_temp.fill_ba_exam(9, '[{"q":"How does Agile change BA documentation?","opts":["Only technical documentation changes","BAs write more documentation in Agile","Documentation is eliminated in Agile","Agile prefers lightweight documentation: user stories + acceptance criteria over formal specifications"],"a":3,"exp":"Agile BA: ''barely sufficient'' documentation. Capture what''s needed for development conversations, not comprehensive specifications. Knowledge lives in the team, not documents.","competency":"ba:product-thinking"},{"q":"What is just-in-time requirements elaboration?","opts":["Writing requirements urgently","Detailing requirements close to when they''ll be developed — avoiding premature detail that becomes waste","Agile planning technique","A sprint planning activity"],"a":1,"exp":"JIT requirements: don''t specify sprint 8''s features in sprint 1. Requirements change as the team learns. Elaborate just before development to maximize accuracy and minimize waste.","competency":"ba:product-thinking"},{"q":"What is the BA''s relationship with the Product Owner?","opts":["BA often supports or fills the PO role — helping with backlog management, stakeholder engagement, and requirements elaboration","BA replaces the Product Owner","BA works for the PO","BA and PO are the same role always"],"a":0,"exp":"In many organizations: BA = PO. In others: BA supports PO with requirements detail while PO handles stakeholder politics and prioritization. Collaboration is key regardless of structure.","competency":"ba:product-thinking"},{"q":"What is continuous requirements discovery in Agile?","opts":["Requirements evolving through ongoing stakeholder conversations, sprint reviews, and user feedback — not a one-time activity","A sprint ceremony","Writing requirements continuously","An Agile technique"],"a":0,"exp":"Agile requirements are never ''done'' — each sprint produces working software that generates new insights and requirements. BAs facilitate this continuous discovery process.","competency":"ba:product-thinking"},{"q":"What is the difference between traditional and Agile BA artifacts?","opts":["Traditional: BRD, FRS, use cases; Agile: user stories, acceptance criteria, story maps — less formal, more collaborative","Traditional artifacts are always better","Same artifacts, different format","Agile has no artifacts"],"a":0,"exp":"Traditional artifacts enable handoffs. Agile artifacts enable conversations. Choose based on context: regulated industries may need traditional; continuous delivery teams benefit from agile artifacts.","competency":"ba:product-thinking"},{"q":"What is the purpose of backlog refinement?","opts":["Writing new user stories","Removing completed stories","Ongoing process of keeping the backlog prioritized, estimated, and detailed enough for development — not a one-time activity","Sprint planning preparation only"],"a":2,"exp":"Refinement keeps the backlog healthy: prioritized (most important first), estimated (team can commit), and detailed (stories near the top are sprint-ready). Regular cadence prevents crises.","competency":"ba:product-thinking"},{"q":"What is WSJF (Weighted Shortest Job First)?","opts":["A story point estimation","A Kanban metric","A sprint planning technique","SAFe''s prioritization formula: Cost of Delay / Job Duration — maximizes economic value delivered per unit of time"],"a":3,"exp":"WSJF prioritizes features delivering the most value in the shortest time. Cost of Delay captures: business value + time criticality + risk reduction. Divide by duration for priority.","competency":"ba:product-thinking"},{"q":"What is the Kano model?","opts":["A customer satisfaction model classifying features as: Must-be (expected), Performance (more=better), Delighter (unexpected value)","A quality management tool","A market research technique","A prioritization matrix"],"a":0,"exp":"Kano: Must-be features (no login = unacceptable). Performance features (faster search = better). Delighters (unexpected personalization = delight). Prioritize to maximize satisfaction.","competency":"ba:product-thinking"},{"q":"What is ''cost of delay'' in prioritization?","opts":["The economic impact of not delivering a feature — revenue lost, market opportunity missed, or risk not mitigated per time period","Developer overtime costs","The cost of a delayed project","A financial metric"],"a":0,"exp":"Cost of delay quantifies procrastination: ''Each week we delay the fraud feature costs $500K in fraud losses.'' This makes prioritization economic rather than political.","competency":"ba:product-thinking"},{"q":"What is a ''ready'' user story?","opts":["A completed story","A story approved by management","A story detailed enough to start development: clear acceptance criteria, estimated, no open questions, dependencies resolved","A story in the sprint backlog"],"a":2,"exp":"Sprint planning fails when stories aren''t ready: unclear requirements, missing acceptance criteria, unresolved dependencies. Ready criteria prevent mid-sprint surprises.","competency":"ba:product-thinking"},{"q":"What is a Feature in SAFe?","opts":["A service the system provides to fulfill a stakeholder need — spans multiple sprints, larger than a story, smaller than an epic","A user story category","A product capability","A release deliverable"],"a":0,"exp":"SAFe Feature: ''Customer self-service returns.'' This enables business value, spans multiple sprints (return initiation, shipping label, refund processing), and fits within a PI.","competency":"ba:product-thinking"},{"q":"What is the BA''s role in PI Planning?","opts":["Writing technical specifications","Preparing features with clear acceptance criteria, business context, and dependencies — enabling teams to plan effectively","Managing the PI schedule","Attending as an observer"],"a":1,"exp":"BA prepares for PI Planning: features are clear and ready, acceptance criteria defined, business context explained. During planning: clarify questions, identify dependencies, validate team plans.","competency":"ba:product-thinking"},{"q":"What is an Enabler in SAFe?","opts":["A dependency management tool","A team support role","Work supporting architectural, infrastructure, or exploration activities — required but doesn''t directly deliver business functionality","A type of epic"],"a":2,"exp":"Enablers: ''Migrate to microservices architecture,'' ''Research AI fraud detection approaches.'' BAs advocate for enablers — they''re investment in future capability, not ''wasted'' backlog capacity.","competency":"ba:product-thinking"},{"q":"What is a Program Increment (PI) in SAFe?","opts":["A timeboxed planning interval (8-12 weeks) during which an ART delivers value — organized around a single PI Planning event","A software release","A project milestone","A sprint grouping"],"a":0,"exp":"PIs provide stability: 8-12 weeks of committed work, planned at PI Planning. BAs define the features that fill each PI based on roadmap priorities and capacity.","competency":"ba:product-thinking"},{"q":"What is the Product Manager vs Product Owner distinction in SAFe?","opts":["PM: program-level, defines features, manages program backlog; PO: team-level, manages team backlog, elaborates stories from features","PO is more senior","PM handles business, PO handles technical","Same role, different names"],"a":0,"exp":"PM operates at the program level: what features does the ART build next quarter? PO operates at the team level: what stories does this team build this sprint from those features?","competency":"ba:product-thinking"},{"q":"What is MoSCoW prioritization?","opts":["A requirements format","A Russian city-based framework","An agile technique","Must have (essential), Should have (important), Could have (desirable), Won''t have (excluded) — quick team alignment on priority"],"a":3,"exp":"MoSCoW is fast and collaborative. ''Must have'' defines the minimum viable scope. Warning: everything becomes ''Must have'' without facilitation — enforce strict Must criteria.","competency":"ba:product-thinking"},{"q":"What is an MVP (Minimum Viable Product)?","opts":["A prototype","A beta version","The smallest product that delivers enough value to real users to generate learning — not minimum in quality, minimum in scope","A proof of concept"],"a":2,"exp":"MVP is about learning, not just delivering. The minimum scope that: delivers real user value, can be released to actual users, and generates feedback for the next iteration.","competency":"ba:product-thinking"},{"q":"What is risk-based prioritization?","opts":["Addressing the highest-risk requirements early — reducing project uncertainty and avoiding late discovery of blocking issues","Removing risky requirements","A risk management framework","Prioritizing the riskiest features last"],"a":0,"exp":"Prioritize requirements with highest technical, business, or integration risk first. Discovering a blocking technical issue in sprint 1 is better than sprint 10.","competency":"ba:product-thinking"},{"q":"How do you prevent the ''everything is priority 1'' problem?","opts":["Agree that all features are equal","Let the PM decide","Let stakeholders decide alone","Force relative prioritization through structured techniques: limited MoSCoW budgets, point allocation, forced ranking"],"a":3,"exp":"Give stakeholders a fixed budget of priority 1 slots. ''You have 5 Must-Haves — which 5?'' Forces difficult but necessary conversations about true priorities.","competency":"ba:product-thinking"},{"q":"What is time-boxing in requirement prioritization?","opts":["A sprint duration","Defining a fixed time period and fitting the highest-value requirements within it — scope adjusts to time, not the other way around","Setting deadlines","A project scheduling technique"],"a":1,"exp":"Time-boxing: ''We have 3 months for MVP. Given that constraint, what are the must-have requirements?'' Time constraint forces prioritization conversations that open-ended scope never does.","competency":"ba:product-thinking"},{"q":"What is digital transformation from a BA perspective?","opts":["A technology upgrade project","Fundamentally rethinking how the business creates value using digital capabilities — not just moving paper processes online","IT modernization","Digitizing existing processes"],"a":1,"exp":"Digital transformation: not ''make the existing form digital'' but ''reimagine the entire customer journey.'' BAs must challenge assumptions about how the business works, not just automate AS-IS.","competency":"ba:product-thinking"},{"q":"What is a platform business model?","opts":["A business model enabling interactions between two or more user groups — like Uber (drivers + riders) or Airbnb (hosts + guests)","A SaaS model","An IT platform","An enterprise software model"],"a":0,"exp":"Platform models create value through network effects: more drivers → better for riders → attracts more drivers. BAs defining platform requirements must understand both sides of the market.","competency":"ba:product-thinking"},{"q":"What is customer experience (CX) analysis in BA?","opts":["Customer satisfaction surveys","User testing","A marketing analysis","Understanding the complete end-to-end customer journey across all touchpoints — requirements span multiple systems and channels"],"a":3,"exp":"CX BA looks at the journey: ''Customer sees ad → visits website → chats with support → places order → receives delivery → returns item.'' Each touchpoint has requirements — none in isolation.","competency":"ba:product-thinking"},{"q":"What is an API strategy and why do BAs need to understand it?","opts":["The plan for exposing business capabilities as APIs — enabling partner integrations, mobile apps, and ecosystem creation","A security framework","A technical development detail","A developer responsibility only"],"a":0,"exp":"BAs defining API requirements shape the business''s digital ecosystem: ''Expose order status API to partners → enable partner integrations → create value beyond our direct product.''","competency":"ba:product-thinking"},{"q":"What is data strategy from a BA requirements perspective?","opts":["A database design plan","Requirements capturing what data to collect, how to use it for analytics, and how to protect it — data as a strategic asset","An IT architecture concern only","Compliance data requirements only"],"a":1,"exp":"Data strategy requirements: ''Capture customer interaction data for personalization,'' ''Build consent management for privacy compliance,'' ''Enable real-time fraud analytics.'' BAs define the data future.","competency":"ba:product-thinking"}]'::jsonb);

-- Module 10: 20 questions
SELECT pg_temp.fill_ba_exam(10, '[{"q":"What is a user story map?","opts":["A backlog visualization","A 2D visualization: user activities across the top, supporting stories below — shows the complete user journey","A product roadmap","A list of user stories"],"a":1,"exp":"Story maps (Jeff Patton) prevent flat backlogs. The horizontal axis shows user journey sequence. Vertical axis shows priority/release. Teams see the forest, not just the trees.","competency":"ba:product-discovery"},{"q":"What is the backbone of a story map?","opts":["The most important stories","The technical architecture","The top row of high-level user activities that define the complete user experience — the user''s story at 30,000 feet","The MVP definition"],"a":2,"exp":"Backbone: Browse Products → Search → Add to Cart → Checkout → Track Order. These activities represent the complete customer journey. Everything else supports them.","competency":"ba:product-discovery"},{"q":"What is a walking skeleton?","opts":["A testing strategy","A minimal prototype","A minimal viable product","The minimum set of stories that implements the end-to-end user journey — thin but complete, proving the architecture works"],"a":3,"exp":"Walking skeleton: one story from each backbone activity that proves the system works end-to-end. Validates architecture and user flow before adding richness.","competency":"ba:product-discovery"},{"q":"How does story mapping facilitate release planning?","opts":["It creates the project schedule","It replaces sprint planning","It''s only for initial planning","Horizontal slices through the map define releases: Release 1 = must-have stories, Release 2 = should-have, Release 3 = nice-to-have"],"a":3,"exp":"Story map slices enable conversation: ''What''s the least we could release and still deliver value?'' Each horizontal cut is a coherent release with its own value proposition.","competency":"ba:product-discovery"},{"q":"What problem does story mapping solve?","opts":["Stakeholder management","Technical design","The flat backlog problem — a prioritized list loses context of how stories relate to each other and the user journey","Sprint velocity estimation"],"a":2,"exp":"Flat backlogs: hard to see gaps, hard to understand scope, easy to optimize for wrong things. Story maps reveal: ''We have 20 checkout stories and 0 return stories — we''ve missed the complete journey.''","competency":"ba:product-discovery"},{"q":"In Teresa Torres''s Opportunity Solution Tree, what sits directly beneath the desired outcome?","opts":["Experiments","Opportunities — unmet needs, pain points, desires","Roadmap dates","Solutions"],"a":1,"exp":"An OST flows outcome → opportunities → solutions → experiments. Opportunities sit beneath the outcome; solutions address opportunities, never the outcome directly.","competency":"ba:product-discovery"},{"q":"The JTBD lens frames a customer need as:","opts":["The competitor they currently use","Their demographic profile","The specific features they request","The progress a customer is trying to make in a given circumstance"],"a":3,"exp":"JTBD focuses on the underlying progress a customer \"hires\" a product to achieve, independent of features/demographics — surfacing the real need.","competency":"ba:product-discovery"},{"q":"Which of these is an outcome, not an output?","opts":["Ship a new onboarding screen","Reduce time-to-first-value so 20% more users activate","Write 30 user stories","Release five features this quarter"],"a":1,"exp":"Outputs are what you build/ship; outcomes are measurable changes in behavior. Discovery targets outcomes (activation lift), not output counts.","competency":"ba:product-discovery"},{"q":"When assumption-mapping a new idea, which assumptions should be tested first?","opts":["The ones the team likes most","The easiest ones to test","High-importance, high-uncertainty (leap-of-faith) assumptions","Low-risk assumptions"],"a":2,"exp":"Prioritize leap-of-faith assumptions — high impact + high uncertainty — because they carry the most risk. Testing easy/low-risk ones first wastes discovery effort.","competency":"ba:product-discovery"},{"q":"A well-formed discovery hypothesis is best expressed as:","opts":["\"The market is big.\"","\"Users will love this.\"","\"We believe [change] will achieve [measurable outcome] for [segment]; we''ll know if [signal].\"","\"We should build feature X.\""],"a":2,"exp":"A testable hypothesis names the change, expected measurable outcome, segment, and success signal — making it falsifiable. Vague beliefs/solution statements aren''t testable.","competency":"ba:product-discovery"},{"q":"The purpose of an MVP in discovery is to:","opts":["Ship a smaller version of the final product","Cut scope to hit a deadline","Learn the most about a risky assumption with the least build","Impress stakeholders"],"a":2,"exp":"An MVP is a learning vehicle — the smallest thing that validates/invalidates a key assumption. It maximizes validated learning per unit of effort, not just a smaller release.","competency":"ba:product-discovery"},{"q":"In a discovery interview, the strongest question is:","opts":["\"Tell me about the last time you faced [problem] — what did you do?\"","\"Do you like this idea?\"","\"How much would you pay for it?\"","\"Would you use a feature that does X?\""],"a":0,"exp":"Story-based, past-behavior questions surface real evidence. Hypothetical/leading questions produce courtesy-biased, unreliable answers.","competency":"ba:product-discovery"},{"q":"Treating one enthusiastic customer''s feature demand as a roadmap mandate risks:","opts":["Ignoring all feedback","Mistaking noise (an anecdote) for signal (a validated pattern)","Over-researching the problem","Building too slowly"],"a":1,"exp":"One loud request is an anecdote, not validated demand. Discovery separates signal (recurring, evidenced patterns) from noise (isolated opinions).","competency":"ba:product-discovery"},{"q":"Which is the strongest evidence of a real need?","opts":["A senior stakeholder''s opinion","Stated intent on a survey","Observed behavior — what users actually do, including current workarounds","A focus-group consensus"],"a":2,"exp":"Behavioral evidence outranks stated intent (prone to bias). Surveys/opinions are weaker supporting signals; what people actually do is the strongest.","competency":"ba:product-discovery"},{"q":"Amazon''s Working Backwards PR/FAQ forces a team to:","opts":["Write press releases for the marketing team","Finalize the architecture first","Skip discovery and start coding","Articulate the customer value and experience before building anything"],"a":3,"exp":"A PR/FAQ written before build clarifies the customer problem, value, and experience up front — exposing weak ideas early and aligning on outcomes, not features.","competency":"ba:product-discovery"},{"q":"Across many discovered opportunities, the most defensible prioritization weighs:","opts":["The CEO''s personal favorite","Outcome impact, strength of evidence, and addressability — not seniority or the loudest voice","Whatever is easiest to build","First-come, first-served"],"a":1,"exp":"Mature prioritization weighs potential outcome impact, how strongly evidence shows the opportunity is real, and how addressable it is — an evidence-based call, not politics.","competency":"ba:product-discovery"},{"q":"A value-vs-effort matrix helps a team:","opts":["Spot high-value, low-effort opportunities to pursue first","Estimate exact delivery dates","Replace discovery entirely","Measure team velocity"],"a":0,"exp":"Value/effort mapping is a fast triage heuristic to surface quick wins and de-prioritize low-value/high-effort items — a prioritization aid, not a delivery estimate.","competency":"ba:product-discovery"},{"q":"A BA uses AI to synthesize 20 discovery interviews into themes. The essential safeguard is:","opts":["Trace each AI-identified theme to actual interview evidence and check for omitted dissent","Use only the AI summary going forward","Accept the themes if they sound coherent","Keep the themes that best fit the existing roadmap"],"a":0,"exp":"AI synthesis can fabricate or flatten signal. Validating themes against real evidence — and checking for dropped minority/contradictory data — keeps discovery honest (links to `ba:ai-prompting`).","competency":"ba:product-discovery"},{"q":"AI clusters discovery data into opportunity groups. The senior BA''s most important critical check is:","opts":["Whether there are exactly five clusters","Whether the chart looks clean","Whether it matches last quarter''s themes","Whether clusters reflect genuine user patterns vs surface-level keyword similarity — and whether important outliers were hidden"],"a":3,"exp":"AI clustering can group on superficial similarity and bury meaningful outliers (often where new opportunities live). The BA validates that clusters represent real, decision-relevant patterns.","competency":"ba:product-discovery"},{"q":"AI surfaces a \"strong opportunity,\" but it rests on three untested assumptions. The correct next step is:","opts":["Design experiments to test the riskiest assumptions before committing — AI surfacing it is not validation","Trust the AI''s confidence score","Ask the AI to re-rank the opportunities","Add it to the roadmap immediately"],"a":0,"exp":"AI can surface and rank candidate opportunities but cannot validate them. The BA still tests the riskiest assumptions with real evidence before commitment.","competency":"ba:product-discovery"}]'::jsonb);

-- Module 11: 20 questions
SELECT pg_temp.fill_ba_exam(11, '[{"q":"Why do BAs need data analysis skills?","opts":["Only data analysts need data skills","For reporting purposes only","BAs use data to validate assumptions, quantify problems, measure baselines, and provide evidence for recommendations","To replace data analysts"],"a":2,"exp":"Data-savvy BAs are more effective: ''Orders take 4 days on average (measured), with 15% taking over 10 days (identified from data), costing $X in cancellations (quantified).'' Not just opinions.","competency":"ba:data-analysis"},{"q":"What is a data baseline in BA context?","opts":["A data quality standard","A database starting point","The current measured performance of a process — the before state that will be compared to after-implementation results","Historical data only"],"a":2,"exp":"Baseline: ''Current average order processing: 4.2 days, 15% error rate, $45 average cost per order.'' Post-implementation measurement compared to baseline proves the solution worked.","competency":"ba:data-analysis"},{"q":"What is quantitative vs qualitative data in BA?","opts":["Qualitative is less reliable","Quantitative: measurable numbers (time, cost, volume); Qualitative: descriptive (observations, interviews, narratives) — both essential for BA","Numbers vs letters","Quantitative is always better"],"a":1,"exp":"Quantitative: ''Response time averages 3.2 seconds.'' Qualitative: ''Users find the interface confusing.'' Both are required for complete requirements — qualitative explains why, quantitative measures what.","competency":"ba:data-analysis"},{"q":"How can data analysis validate stakeholder requirements?","opts":["Analyze actual usage data to validate: are users doing what stakeholders say they''re doing? Are problems as frequent as claimed?","After implementation only","Only through user testing","Data can''t validate requirements"],"a":0,"exp":"Data validation: stakeholder claims ''we get 1000 complaints daily about X.'' Log analysis: 47 complaints daily about X. Data reveals the actual problem size vs perceived size.","competency":"ba:data-analysis"},{"q":"What is data-driven requirements specification?","opts":["Requirements validated by data scientists","Using data analysis to quantify requirements: ''System shall support peak load of 500 concurrent users'' — derived from actual usage analysis","Requirements written in SQL","Automated requirements generation"],"a":1,"exp":"Data-driven specs are more accurate: actual current load analysis reveals peak of 340 users. NFR becomes ''500 concurrent users (50% headroom above measured peak of 340)'' — not a guess.","competency":"ba:data-analysis"},{"q":"Why should BAs learn SQL?","opts":["For documentation purposes","SQL is only for developers","To replace data analysts","SQL enables BAs to self-serve data analysis — validate assumptions, check data quality, and answer business questions without waiting for technical support"],"a":3,"exp":"SQL-fluent BAs are faster and more autonomous: ''Let me check that assumption in the data'' instead of ''Can you write a query for me?'' Self-service data analysis accelerates BA work significantly.","competency":"ba:data-analysis"},{"q":"What is data profiling?","opts":["Analyzing a dataset to understand its structure, quality, and content: row counts, nulls, distributions, value ranges, relationships","A database design technique","A business analysis method","Creating user profiles"],"a":0,"exp":"Data profiling before requirements: understand what data actually exists, its quality, and limitations. Prevents: ''We''ll use field X for this'' when field X is 40% null in production.","competency":"ba:data-analysis"},{"q":"What SQL query answers ''how often does X happen?''","opts":["SELECT category FROM table WHERE count > 1","SELECT category, COUNT(*) FROM table GROUP BY category ORDER BY COUNT(*) DESC","SELECT MAX(count) FROM table","SELECT * FROM table"],"a":1,"exp":"Frequency analysis: SELECT order_status, COUNT(*) as count FROM orders GROUP BY order_status. Reveals: completed=8000, cancelled=1200, pending=450. Data for requirements justification.","competency":"ba:data-analysis"},{"q":"How can BAs use SQL to validate requirements?","opts":["SQL is for developers to validate code","Writing technical specs in SQL","Automated testing with SQL","Query production data to verify: do the volumes match estimates, are edge cases as rare as assumed, does the data structure support the requirement"],"a":3,"exp":"Requirement: ''Users can change orders within 1 hour of placement.'' SQL validation: ''SELECT COUNT(*) FROM orders WHERE status_changed < DATEADD(hour,1,created_at).'' Is this actually requested?","competency":"ba:data-analysis"},{"q":"What is a BA''s relationship with data in requirements analysis?","opts":["BAs analyze data after implementation only","Data informs every aspect of BA work: quantify problems, baseline performance, validate assumptions, and measure solution success","Data is always provided by data teams","BAs only work with people, not data"],"a":1,"exp":"Data-savvy BAs: use data to quantify problems (not just describe them), validate stakeholder claims, set measurable acceptance criteria, and demonstrate solution value post-implementation.","competency":"ba:data-analysis"},{"q":"What is the difference between a KPI and a metric?","opts":["KPIs are critical measures directly linked to strategic success; metrics measure activities that may or may not be strategic","Metrics are financial only","Same thing","KPIs are more important"],"a":0,"exp":"KPI: ''Customer satisfaction score'' (directly impacts retention and revenue). Metric: ''Number of support tickets'' (activity measure, not directly tied to strategy without context).","competency":"ba:data-analysis"},{"q":"What is a leading indicator?","opts":["A financial metric","A lagging performance indicator","A measure that predicts future outcomes — allows proactive action before the outcome is fixed","A metric from last month"],"a":2,"exp":"Leading: customer complaint rate (predicts churn). Lagging: churn rate (measures past behavior already baked in). BAs should define both — leading indicators enable preventive action.","competency":"ba:data-analysis"},{"q":"What makes a metric ''actionable''?","opts":["A real-time metric","A metric that can be automated","A metric that reveals something you can do something about — improving it is within the team''s control and influences outcomes","A metric with a threshold"],"a":2,"exp":"Actionable: ''Order error rate'' — team can fix the process. Not actionable: ''Weather on delivery day'' — team can''t control it. BAs define metrics teams can actually influence.","competency":"ba:data-analysis"},{"q":"What is a benefit realization metric?","opts":["A measure demonstrating that a solution delivered the promised business benefits — connecting investment to outcomes","A project completion metric","A customer satisfaction score","A financial accounting metric"],"a":0,"exp":"Benefit realization: ''We promised 40% reduction in processing time. 6 months post-go-live: processing time reduced 43%.'' Closes the loop on BA''s requirements and business case.","competency":"ba:data-analysis"},{"q":"Why is baseline measurement critical before solution implementation?","opts":["For budget justification only","For project documentation","Without a baseline, you can''t measure improvement — you need current state numbers to compare with post-implementation results","Regulatory requirement"],"a":2,"exp":"Without baseline: ''The solution improved processing time.'' By how much? From what? A baseline enables: ''Processing time reduced from 4.2 days to 1.1 days — a 74% improvement.''","competency":"ba:data-analysis"},{"q":"What is a wireframe in business analysis?","opts":["A low-fidelity sketch of a user interface used to communicate requirements and gather feedback before development","A technical architecture diagram","A finalized design","A database schema"],"a":0,"exp":"Wireframes communicate UI requirements without the cost of full design. Stakeholders react to the structure and flow rather than colors and fonts. Faster feedback, cheaper changes.","competency":"ba:data-analysis"},{"q":"When should a BA create a prototype?","opts":["Always — prototypes replace requirements","After requirements are finalized","When stakeholders struggle to articulate requirements from description — showing a working model triggers concrete, actionable feedback","Only for complex systems"],"a":2,"exp":"Prototypes are elicitation tools: ''I can''t describe what I want, but when I see this, I know it''s not right.'' Prototypes accelerate requirements clarity for UI-heavy requirements.","competency":"ba:data-analysis"},{"q":"What is the purpose of a requirements traceability matrix visualization?","opts":["A project status dashboard","A stakeholder communication tool","To verify complete coverage: every business requirement traces to at least one functional requirement and test case","To create a beautiful chart"],"a":2,"exp":"RTM visualization reveals gaps: green (covered), yellow (partial), red (not covered). Immediately shows which business requirements have no corresponding functional specs or test cases.","competency":"ba:data-analysis"},{"q":"What chart type best shows process performance over time?","opts":["Bar chart","Pie chart","Scatter plot","Line chart — shows trend direction and rate of change over a time series"],"a":3,"exp":"Line charts reveal trends: is processing time improving or degrading? Is the trend linear or accelerating? Time series data needs line charts — pie charts hide temporal dynamics.","competency":"ba:data-analysis"},{"q":"What is the benefit of visual over text requirements?","opts":["Text is always more precise","Visuals reduce ambiguity, enable faster comprehension, surface gaps, and are accessible to non-technical stakeholders","Visuals are always better than text","Visuals are only for presentations"],"a":1,"exp":"A process diagram communicates relationships and flows in seconds that paragraphs can''t. Ambiguities in text requirements become obvious in diagrams. Use both — complementary strengths.","competency":"ba:data-analysis"}]'::jsonb);

-- Module 12: 15 questions
SELECT pg_temp.fill_ba_exam(12, '[{"q":"What dimensions should a feasibility analysis cover?","opts":["User acceptance and technical feasibility","Cost and timeline only","Technical only","Technical, financial, operational, scheduling, and legal/regulatory feasibility"],"a":3,"exp":"Complete feasibility: Can it be built? (technical) Can we afford it? (financial) Can we operate it? (operational) Can we do it in time? (schedule) Are there regulatory barriers? (legal)","competency":"ba:solution-eval"},{"q":"What is a proof of concept (PoC)?","opts":["A prototype for demonstrations","A pilot deployment","A small-scale experiment validating that a proposed approach is technically feasible before committing to full development","A vendor demo"],"a":2,"exp":"PoCs answer: ''Can we actually do this?'' Build the riskiest assumption first. If the PoC fails, you''ve failed fast and cheaply. If it succeeds, you have confidence to proceed.","competency":"ba:solution-eval"},{"q":"What is a decision matrix?","opts":["A weighted scoring tool comparing multiple options against defined criteria — making complex decisions more objective","A project decision log","A risk assessment tool","A prioritization framework"],"a":0,"exp":"Decision matrix: define criteria (cost, risk, timeline, fit) with weights. Score each option against each criterion. Multiply scores by weights and total. Reduces bias in option selection.","competency":"ba:solution-eval"},{"q":"What factors favor buying vs building a solution?","opts":["Cost alone determines buy vs build","Building always gives better control","Buying: available commodity solutions exist, time-to-market matters, customization isn''t needed; Building: competitive differentiator, no existing solution fits","Buying is always better"],"a":2,"exp":"Buy when: ERP, CRM, HR systems are commodity. Build when: the process is your competitive differentiator. Wrong choice: building custom accounting software instead of buying QuickBooks.","competency":"ba:solution-eval"},{"q":"What is a business case?","opts":["A project plan","A requirements document","A document justifying the investment: problem statement, options analysis, recommended solution, costs, benefits, and risks","A legal case"],"a":2,"exp":"Business cases enable investment decisions: ''We recommend Option B: $400K investment, $1.2M annual savings, 4-month payback period, moderate technical risk.'' Ties solution to financial value.","competency":"ba:solution-eval"},{"q":"What is the difference between verification and validation?","opts":["Verification: are we building it right? (matches requirements); Validation: are we building the right thing? (meets business need)","Same thing","Validation is for QA only","Verification is more important"],"a":0,"exp":"You can verify a system perfectly meets all requirements and still fail validation if the requirements were wrong. Both are necessary. BAs focus on validation.","competency":"ba:solution-eval"},{"q":"What is UAT (User Acceptance Testing)?","opts":["Business users testing that the system meets their actual needs and acceptance criteria — final validation before go-live","Performance testing","Technical testing by the QA team","Automated regression testing"],"a":0,"exp":"UAT is the business''s final check. Business users, not QA, verify the system works for their actual workflows. Defects found here are expensive — validate requirements earlier.","competency":"ba:solution-eval"},{"q":"What is a go-live readiness checklist?","opts":["A deployment checklist","A comprehensive verification that all aspects of deployment are ready: training, data, support, rollback plan, stakeholder communication","A project completion report","A technical deployment guide"],"a":1,"exp":"Go-live readiness: users trained, data migrated, support team ready, rollback plan tested, stakeholders communicated, documentation complete. Missing any item risks a failed go-live.","competency":"ba:solution-eval"},{"q":"What is a post-implementation review?","opts":["A technical audit","A lessons learned session only","An assessment after go-live: did the solution solve the problem, were benefits realized, what should be done differently next time","A customer satisfaction survey"],"a":2,"exp":"PIR closes the BA loop: ''We said we''d reduce processing time 50%. Did we? What worked? What didn''t? What requirements were we wrong about?'' Drives organizational learning.","competency":"ba:solution-eval"},{"q":"What is delta testing?","opts":["Testing only what changed between versions — reducing regression test scope while ensuring changes work correctly","A testing framework","A type of UAT","Greek alphabet testing"],"a":0,"exp":"Delta testing: after an upgrade, test changed functionality plus its dependencies. Full regression is expensive; delta testing balances efficiency with risk coverage.","competency":"ba:solution-eval"},{"q":"What is the purpose of a business case?","opts":["A project plan summary","To request a budget","A technical specification","To justify an investment by demonstrating value exceeds cost — enabling informed organizational investment decisions"],"a":3,"exp":"Business cases enable portfolio decisions: ''Should we invest $500K in this vs that alternative?'' The BA''s analysis makes the decision explicit, rational, and documented.","competency":"ba:solution-eval"},{"q":"What are tangible benefits?","opts":["Real benefits that matter","Quantifiable financial benefits: cost savings, revenue increase, headcount reduction — directly measurable in dollars","Benefits from the project","Benefits visible to stakeholders"],"a":1,"exp":"Tangible: ''$200K/year in reduced manual processing costs.'' Intangible: ''Improved employee satisfaction.'' Both matter, but tangible benefits make financial justification easier.","competency":"ba:solution-eval"},{"q":"What is Net Present Value (NPV)?","opts":["Current project value","The present value of all future cash flows discounted at the cost of capital — positive NPV = value-creating investment","Revenue minus costs","A financial metric for BAs"],"a":1,"exp":"NPV accounts for time value of money: $100K benefit in year 3 is worth less than $100K today. Positive NPV means the investment creates value. Essential for multi-year benefit cases.","competency":"ba:solution-eval"},{"q":"How should BAs handle intangible benefits?","opts":["Convert all benefits to money","Ignore them — only quantifiable benefits matter","Present them separately from financial analysis","Attempt to quantify where possible, acknowledge and describe where not — don''t dismiss what can''t be measured precisely"],"a":3,"exp":"Intangibles matter: customer satisfaction, employee morale, regulatory compliance risk reduction. Attempt quantification: ''10% satisfaction improvement historically correlates to 5% retention improvement.''","competency":"ba:solution-eval"},{"q":"What is sensitivity analysis in a business case?","opts":["A risk analysis technique","Testing how the ROI changes if key assumptions vary — showing decision-makers the robustness of the business case","A financial modeling tool","A stakeholder sensitivity test"],"a":1,"exp":"Sensitivity analysis: ''If benefits are 20% lower than projected, ROI drops from 45% to 28% — still positive.'' Shows decision-makers the margin of safety and key assumptions to monitor.","competency":"ba:solution-eval"}]'::jsonb);

-- Module 13: 45 questions
SELECT pg_temp.fill_ba_exam(13, '[{"q":"What is process mining?","opts":["A data mining technique","Mining for process improvements manually","A database analytics method","Discovering actual business processes from system event logs — revealing what really happens vs what''s documented"],"a":3,"exp":"Process mining analyzes event logs (SAP, Salesforce, ERP) to reconstruct actual process flows. Often reveals: unofficial workarounds, frequent exceptions, and undocumented process variants.","competency":"ba:ai-analysis"},{"q":"What is the main insight from process mining?","opts":["Identifies user errors only","Finds technical system issues","Actual processes differ significantly from documented ones — revealing workarounds, exceptions, and inefficiencies not captured in AS-IS documentation","Confirms documented processes are accurate"],"a":2,"exp":"Process mining consistently reveals: processes that look clean on paper are actually chaotic in reality, with 40-60% of cases following non-standard paths. Critical for accurate TO-BE design.","competency":"ba:ai-analysis"},{"q":"What is simulation in process analysis?","opts":["A demonstration to stakeholders","A software testing technique","Creating a training simulation","Modeling a TO-BE process with realistic data to predict performance before implementation — safe testing of process changes"],"a":3,"exp":"Simulation: ''If we add one resource to step 3 and automate step 7, average cycle time drops from 4 days to 1 day.'' Validate improvements before committing resources to implementation.","competency":"ba:ai-analysis"},{"q":"How can AI accelerate BPMN creation?","opts":["Only for simple linear processes","Generate initial BPMN diagrams from interview transcripts, meeting notes, or process descriptions — BA validates and refines","AI cannot create process models","AI replaces BA process modeling"],"a":1,"exp":"Describe a process to Claude/ChatGPT and ask for BPMN XML or a process structure. AI provides the starting scaffold; BA validates against actual stakeholder interviews.","competency":"ba:ai-analysis"},{"q":"What is Celonis used for?","opts":["A leading process mining platform that analyzes ERP/CRM data to reveal actual process execution and identify improvement opportunities","An RPA platform","A BI visualization tool","Project management"],"a":0,"exp":"Celonis connects to SAP, Salesforce, and other systems to replay millions of transactions as process flows. Identifies bottlenecks, compliance issues, and automation opportunities automatically.","competency":"ba:ai-analysis"},{"q":"How can AI augment BA data analysis?","opts":["AI only creates charts","AI replaces BA analysis","AI is unreliable for BA work","AI processes large data volumes quickly, identifying patterns and anomalies that inform requirements — BA interprets and validates findings"],"a":3,"exp":"AI analyzes 10 million transactions and surfaces: ''Orders containing item X have 3x higher cancellation rate.'' This data insight directly informs a requirements investigation.","competency":"ba:ai-analysis"},{"q":"What is natural language data querying?","opts":["Querying databases or analytics tools using plain English questions rather than SQL — democratizing data access for BAs","A chatbot feature","Voice-based data entry","Asking users questions about data"],"a":0,"exp":"Tools like ThoughtSpot, Power BI Q&A: ''What are the top 10 reasons for order cancellations this quarter?'' → automatic visualization. No SQL required for common queries.","competency":"ba:ai-analysis"},{"q":"How can AI help validate requirements against data?","opts":["AI approves all requirements","AI creates requirements from data","Only manual validation works","AI analyzes production data to check if requirements reflect actual user behavior and system usage patterns"],"a":3,"exp":"Requirement: ''Users can place up to 5 orders per day.'' AI analyzes order history: 99.8% of users place ≤ 2 orders per day, 0.01% place > 5. Data validates the requirement ceiling.","competency":"ba:ai-analysis"},{"q":"What is AI-generated narrative analytics?","opts":["An AI reporting tool","Automated dashboard creation","AI writing stories about data","AI automatically generating text descriptions of data insights — converting charts and metrics into plain language explanations"],"a":3,"exp":"Power BI Smart Narrative, ThoughtSpot Sage: ''Revenue is $2.3M this month, up 15% vs last month, driven primarily by 23% growth in the Enterprise segment.'' Saves BA hours of narrative writing.","competency":"ba:ai-analysis"},{"q":"What human judgment remains critical in AI-augmented BA analysis?","opts":["AI handles all analysis","Only presentation skills","Interpreting findings in business context, validating AI insights against domain knowledge, and deciding what matters for stakeholders","Technical data validation only"],"a":2,"exp":"AI finds patterns; BAs determine which patterns matter. ''AI found X correlates with Y'' → BA determines: is this causal or coincidental? Is it actionable? What should we do about it?","competency":"ba:ai-analysis"},{"q":"How will AI change the BA role?","opts":["AI replaces BAs entirely","Only junior BA tasks are automated","No significant change","AI automates documentation and analysis tasks — BAs focus on stakeholder relationships, judgment, and strategic problem definition"],"a":3,"exp":"AI handles: requirements drafting, process diagramming, gap analysis. BAs focus on: understanding organizational politics, facilitating complex stakeholder negotiations, and strategic problem definition.","competency":"ba:ai-analysis"},{"q":"What is the BA/Product Manager convergence?","opts":["A role confusion problem","Only in tech companies","Digital-first organizations merging BA (requirements depth) with PM (product strategy) into product-focused roles","A trend to avoid"],"a":2,"exp":"In digital companies, the product manager owns the full stack: strategy, requirements, and delivery. Traditional BA skills (elicitation, modeling, stakeholder management) are core product management competencies.","competency":"ba:ai-analysis"},{"q":"What is citizen development and the BA''s role?","opts":["Low-code/no-code tools enabling business users to build solutions — BAs govern, guide, and enable this movement","An IT initiative","Non-citizens developing software","A threat to BA jobs"],"a":0,"exp":"Low-code tools (Power Apps, Salesforce Flow) let business users build apps. BAs: define governance, mentor citizen developers on requirements best practices, and ensure solutions meet quality standards.","competency":"ba:ai-analysis"},{"q":"What is strategic BA?","opts":["Advanced BA certification","BAs operating at the organizational level: shaping strategy, identifying capability gaps, and driving transformation — not just project requirements","A management consulting role","BA for large enterprises only"],"a":1,"exp":"Strategic BAs: ''The real problem isn''t the ordering system — it''s the organizational strategy of competing on price when we should compete on service. Let''s reframe the initiative.''","competency":"ba:ai-analysis"},{"q":"What is the most future-proof BA skill?","opts":["Technical tools knowledge","AI tool proficiency","Human-centered thinking — understanding what people truly need, facilitating consensus, and translating complexity into actionable requirements","Documentation skills"],"a":2,"exp":"AI handles tools. What AI cannot: deeply understand unstated human needs, navigate organizational politics, build trust with resistant stakeholders, and reframe problems creatively. These are BA superpowers.","competency":"ba:ai-analysis"},{"q":"A BA uses an LLM to draft functional requirements from a meeting transcript. What is the BA''s correct relationship to that output?","opts":["Send the generated requirements straight to developers to save time","Treat the output as a first draft to review, validate against stakeholder intent, and refine","Assume the transcript was fully captured because the model processed all of it","Use it only if the grammar is perfect"],"a":1,"exp":"AI accelerates drafting, but the BA stays accountable. Generated requirements are a starting draft to validate for accuracy/completeness and refine before use.","competency":"ba:ai-prompting"},{"q":"Which prompt practice MOST improves generated requirements and reduces ambiguity?","opts":["Request as many requirements as possible regardless of relevance","Use the highest creativity/temperature setting","Ask \"write the requirements\" with no other context","Provide role, context, the source material, the target format/template, and explicit constraints (\"atomic, testable, no solutioning\")"],"a":3,"exp":"Role + context + source + output format + constraints yields atomic, testable, scope-bounded requirements. Vague prompts and high temperature increase ambiguity and fabrication.","competency":"ba:ai-prompting"},{"q":"A BA uses AI to synthesize themes and conflicts from 12 interview transcripts. The single most important validation step before sharing is:","opts":["Reword the synthesis to sound more executive","Drop minority viewpoints to simplify the summary","Trace each theme and conflict back to specific statements in the source transcripts","Run it through a second AI model"],"a":2,"exp":"AI synthesis can omit, over-generalize, or invent. Tracing each theme/conflict to real statements keeps it trustworthy and prevents silent loss of dissenting input.","competency":"ba:ai-prompting"},{"q":"An AI synthesis shows strong consensus, but the BA recalls two stakeholders strongly disagreeing. Most likely explanation?","opts":["The model smoothed real conflict into a plausible-sounding consensus (synthesis bias/omission)","The stakeholders changed their minds","AI models cannot detect disagreement","The disagreement was unimportant"],"a":0,"exp":"LLMs tend to produce agreeable, coherent summaries and can flatten conflict. The BA must prompt for dissent/edge cases and verify against source — unsurfaced conflict is a major discovery risk.","competency":"ba:ai-prompting"},{"q":"What is the best use of AI for user stories?","opts":["Auto-generate and commit them to the backlog without review","Generate candidate stories the team then refines and validates against real user value","Use it only when no stakeholders are available","Replace backlog refinement entirely"],"a":1,"exp":"AI is a drafting accelerator. Generated stories are candidates; the team still validates value, splits, and refines. AI replaces neither refinement nor stakeholder validation.","competency":"ba:ai-prompting"},{"q":"An LLM returns stories all beginning \"As a user…\". The best prompt refinement is:","opts":["Ask for more stories","Tell it to be more creative","Supply specific personas, their goals, and INVEST criteria, and ask for persona-specific value","Accept them — \"As a user\" is always fine"],"a":2,"exp":"Generic \"as a user\" stories lack real persona value. Personas + goals + INVEST force specific, independent, valuable, testable stories.","competency":"ba:ai-prompting"},{"q":"Before AI-generated Gherkin acceptance criteria are \"done,\" the BA must verify:","opts":["They read confidently","They are testable, cover edge/negative cases, and match the story''s real intent and business rules","There are at least five scenarios","The Gherkin syntax is valid"],"a":1,"exp":"Valid syntax and volume aren''t quality. Criteria must be testable, reflect true business rules, and include the edge/negative paths AI commonly omits.","competency":"ba:ai-prompting"},{"q":"AI-generated criteria look thorough but omit what a regulated system needs for a failed transaction. This illustrates:","opts":["AI optimizes for the happy path and under-represents negative/compliance scenarios unless prompted","Gherkin cannot express failure scenarios","The story was too detailed","Acceptance criteria don''t cover failures"],"a":0,"exp":"LLMs gravitate to common happy-path patterns. The BA must explicitly prompt for failure, exception, and regulatory scenarios — and validate them — especially in regulated domains.","competency":"ba:ai-prompting"},{"q":"The appropriate way to use AI when producing a BRD is to:","opts":["Draft and structure sections with AI, then validate content, fill gaps, and own the final document","Avoid AI entirely for formal documents","Use AI only for spelling","Generate it and sign off without review"],"a":0,"exp":"AI accelerates structure and drafting, but the BA owns accuracy, completeness, and sign-off. The BRD is an accountable artifact, not raw AI output.","competency":"ba:ai-prompting"},{"q":"To reduce hallucinated facts when an LLM drafts a BRD, the most effective technique is:","opts":["Ask it to \"be accurate\"","Increase the response length","Add a longer system prompt about professionalism","Ground it with the actual source artifacts and instruct it to use only provided sources and flag unknowns"],"a":3,"exp":"Grounding (providing/retrieving sources) plus \"use only supplied material and mark gaps\" is the strongest practical defense against fabricated content.","competency":"ba:ai-prompting"},{"q":"A BA asks an LLM to turn a process narrative into BPMN. The key validation is:","opts":["Confirm gateways, sequence flows, roles/swimlanes, and exception paths match the real process, with stakeholders","Confirm it has at least 10 tasks","Confirm the diagram is colorful","Confirm the XML is valid"],"a":0,"exp":"AI can produce structurally valid but semantically wrong models (missing exceptions, wrong gateway logic, misassigned roles). Validation against the real process with stakeholders is essential.","competency":"ba:ai-prompting"},{"q":"Why should an AI-generated \"to-be\" process model never be final on its own?","opts":["To-be models are unnecessary","AI cannot draw diagrams","BPMN is always manual","It reflects the model''s assumptions, not validated stakeholder agreement on the future state"],"a":3,"exp":"A to-be process is an agreed design decision. AI can propose options, but the future state must be validated and agreed with stakeholders.","competency":"ba:ai-prompting"},{"q":"The best way to validate a set of AI-generated requirements for a high-stakes project is to:","opts":["Trust it if the model expressed high confidence","Cross-check against source evidence, review with SMEs/stakeholders, and test for completeness, consistency, and feasibility","Re-run the same prompt and compare","Spell-check and ship"],"a":1,"exp":"Validation triangulates: trace to sources, human SME/stakeholder review, and structured quality checks. Model self-confidence is not evidence of correctness.","competency":"ba:ai-prompting"},{"q":"An enterprise wants AI-assisted requirements at scale. Which control gives the strongest quality assurance without killing velocity?","opts":["Ban AI use to avoid risk","A human-in-the-loop validation gate with defined acceptance criteria, source traceability, and audit sampling of AI-assisted artifacts","Rely on the vendor''s model-accuracy claims","Let any analyst publish AI output freely"],"a":1,"exp":"Scaled assurance = a defined human gate (acceptance criteria + traceability) plus audit sampling. Bans kill the benefit; free publishing removes accountability; vendor claims aren''t project evidence.","competency":"ba:ai-prompting"},{"q":"In AI-generated requirements, a \"hallucination\" is:","opts":["A formatting glitch","A grammar error","A requirement a stakeholder rejected","Plausible-sounding content the model fabricated that isn''t supported by the source or reality"],"a":3,"exp":"A hallucination is confident, fluent, but unsupported/fabricated content — especially dangerous in requirements because it looks credible and survives casual review.","competency":"ba:ai-prompting"},{"q":"AI-drafted requirements cite a specific regulation clause and a metric no one provided. The safest BA response is:","opts":["Flag both as unverified, trace to authoritative sources, and remove or correct them before the artifact proceeds","Keep the regulation but drop the metric","Keep them — specific citations are usually right","Ask the model if it is sure"],"a":0,"exp":"Fabricated citations/figures are classic hallucinations with legal/compliance risk. Verify against authoritative sources and remove/correct; model self-assessment is unreliable.","competency":"ba:ai-prompting"},{"q":"How does requirements traceability specifically mitigate AI-generation risk?","opts":["It replaces stakeholder review","Every requirement links back to a validated source and forward to design/tests, so unsupported (hallucinated) items are exposed as having no origin","It improves prompt quality","It makes the document longer"],"a":1,"exp":"A traceability matrix forces each requirement to have a real source and downstream link. AI-fabricated items trace to nothing — making traceability a direct hallucination control.","competency":"ba:ai-prompting"},{"q":"A program uses AI to generate requirements across 8 workstreams. The traceability practice that best protects auditability is:","opts":["Trust the backlog tool''s history","Only trace requirements that changed","Store all AI chats in a folder","Tag each requirement with its source evidence and an AI-assisted-origin flag, maintained in a reviewable/auditable traceability matrix"],"a":3,"exp":"Auditability needs per-requirement source linkage plus provenance (AI-assisted flag) in a reviewable matrix — enabling targeted audit of AI-origin items and defensible evidence trails.","competency":"ba:ai-prompting"},{"q":"Before pasting confidential stakeholder data into a public AI tool to summarize it, the BA must first:","opts":["Proceed — summaries are low risk","Confirm the data-handling/privacy policy and use an approved compliant tool, or de-identify the data","Ask stakeholders to remove their names afterward","Use the most popular tool available"],"a":1,"exp":"Feeding confidential/PII into unapproved tools can breach GDPR/HIPAA/contracts. Governance (approved tooling, data rules, de-identification) comes before convenience.","competency":"ba:ai-prompting"},{"q":"An organization is defining governance for AI-assisted analysis. The strongest baseline is:","opts":["Approved tooling + data-handling rules + human-in-the-loop validation + provenance/traceability + periodic audit","Blocking all AI tools","A policy document no one enforces","Trusting analysts to \"use AI responsibly\""],"a":0,"exp":"Effective governance layers controls: vetted tools, data rules, mandatory human validation, output provenance/traceability, and audit. Policy-only, trust-only, and ban-only all fail in practice.","competency":"ba:ai-prompting"},{"q":"A BA uses AI to extract requirements from 200 legacy pages. \"Normalization\" means:","opts":["Translating them to another language","Deleting the non-functional ones","Making the document shorter","Rewriting them into a consistent, atomic, deduplicated form so they can be compared and traced"],"a":3,"exp":"Normalization standardizes extracted requirements into a consistent, comparable form — a core AI-assisted analysis step beyond raw extraction.","competency":"ba:ai-analysis"},{"q":"AI clusters 300 requirements and flags a capability with almost none. The analyst reads this as:","opts":["Proof the capability is unimportant","A possible coverage gap to investigate — a signal, not a conclusion","A reason to delete that capability","An AI error to ignore"],"a":1,"exp":"AI clustering surfaces candidate gaps; the analyst investigates with sources/stakeholders. AI flags, the analyst concludes.","competency":"ba:ai-analysis"},{"q":"Using AI to generate user stories and acceptance criteria, the analyst''s core value-add is:","opts":["Judging fit to real user needs, business rules, and edge cases, then refining","Typing speed","Accepting whatever is generated","Generating the largest possible volume"],"a":0,"exp":"AI drafts; the analyst curates — validating fit, covering edge cases, refining. The professional skill is judgment, not volume.","competency":"ba:ai-analysis"},{"q":"AI generates functional acceptance criteria but no performance, security, or accessibility criteria. This reflects:","opts":["That the story is complete","That AI under-generates non-functional requirements unless explicitly directed and reviewed","That NFRs don''t matter","A formatting issue"],"a":1,"exp":"AI tends to produce happy-path functional criteria and under-represent NFRs. The analyst deliberately elicits and adds them.","competency":"ba:ai-analysis"},{"q":"The strongest analytical use of AI across a 150-requirement set is to:","opts":["Make the font consistent","Approve the set automatically","Estimate delivery dates","Detect contradictions, overlaps, and dependencies for the analyst to resolve"],"a":3,"exp":"AI excels at surfacing contradictions/overlaps/dependencies across large sets — high-value leverage the analyst then resolves with stakeholders.","competency":"ba:ai-analysis"},{"q":"AI asserts a requirement is \"mandated by regulation X.\" The professional posture is:","opts":["Ask AI to be more confident","Accept it — AI cited a regulation","Remove all regulatory requirements","Verify the claim against the authoritative source before relying on it, and record the source"],"a":3,"exp":"Analyst rigor verifies AI claims against authoritative sources and records provenance — especially regulatory assertions. AI accelerates; the analyst is accountable.","competency":"ba:ai-analysis"},{"q":"An analyst uses AI for trade-off analysis between two options. AI''s appropriate role is to:","opts":["Structure the criteria and surface pros/cons and impacts for human judgment","Replace stakeholder input","Make the final decision","Hide the weaker option"],"a":0,"exp":"AI structures the decision to support human judgment; it informs the trade-off, it doesn''t own the decision, which needs stakeholder context and accountability.","competency":"ba:ai-analysis"},{"q":"AI-generated dependency maps between requirements are most useful when the analyst:","opts":["Ignores them","Treats them as final truth","Publishes them unchecked","Uses them as a draft to validate with the team, catching missed or invented links"],"a":3,"exp":"AI dependency maps are a fast first draft that can miss or invent links; the analyst validates before they drive planning.","competency":"ba:ai-analysis"},{"q":"Which output most warrants mandatory human review/sign-off?","opts":["A brainstormed list of names","A reformatted backlog","High-stakes outputs affecting safety, legal, financial, or regulatory decisions","A meeting summary"],"a":2,"exp":"Human-in-the-loop intensity scales with stakes; safety/legal/financial/regulatory outputs demand mandatory review and sign-off.","competency":"ba:ai-analysis"},{"q":"To keep AI-assisted analysis auditable, the analyst should:","opts":["Avoid documentation to save time","Record what was AI-assisted, the sources used, and who reviewed/approved each output","Trust the tool''s logs only","Delete prompts after use"],"a":1,"exp":"Auditability requires recording AI-assisted provenance (what/sources/reviewer/approval) so outputs are traceable and defensible.","competency":"ba:ai-analysis"}]'::jsonb);

-- Module 14: 20 questions
SELECT pg_temp.fill_ba_exam(14, '[{"q":"Under GDPR, \"data minimization\" requires a BA to write requirements that:","opts":["Store all collected data indefinitely","Collect only the personal data necessary for the stated purpose","Encrypt every field regardless of need","Collect as much personal data as possible for future use"],"a":1,"exp":"Data minimization (Art. 5) limits collection to what''s necessary for a specified, legitimate purpose. BAs scope requirements accordingly.","competency":"ba:compliance"},{"q":"A feature lets users export and delete their account data. Which GDPR rights is the BA capturing?","opts":["Right to unlimited storage","Right to anonymous payment","Right to data portability (export) and right to erasure (delete)","Right to profit-sharing and anonymity"],"a":2,"exp":"Export = data portability (Art. 20); delete = erasure / \"right to be forgotten\" (Art. 17). BAs turn data-subject rights into functional requirements.","competency":"ba:compliance"},{"q":"In a US healthcare system, which data category triggers HIPAA requirements?","opts":["Protected Health Information (PHI)","Employee parking records","Aggregated anonymous statistics only","Publicly available marketing data"],"a":0,"exp":"HIPAA governs PHI — individually identifiable health data. BAs flag PHI flows and apply HIPAA privacy/security requirements.","competency":"ba:compliance"},{"q":"A vendor will process PHI on the organization''s behalf. The requirements must account for:","opts":["No special agreement","A standard NDA only","A marketing consent form","A Business Associate Agreement (BAA) governing the vendor''s PHI handling"],"a":3,"exp":"Any vendor handling PHI is a Business Associate requiring a BAA. Integration requirements must include the contractual/control obligations.","competency":"ba:compliance"},{"q":"PCI-DSS applies to systems that handle:","opts":["Cardholder / payment card data","Public website content","Only health data","Only employee HR data"],"a":0,"exp":"PCI-DSS governs storage, processing, and transmission of cardholder data. Payment features must be scoped to PCI controls.","competency":"ba:compliance"},{"q":"To reduce PCI-DSS scope for checkout, the strongest requirement a BA can specify is:","opts":["Store full card numbers in the app database for convenience","Log card numbers for debugging","Email card numbers to support for refunds","Use tokenization / a compliant third-party processor so raw card data never touches our systems"],"a":3,"exp":"Outsourcing card capture/tokenization keeps raw PAN out of your environment, shrinking PCI scope. Storing/logging/emailing card data expands scope and risk.","competency":"ba:compliance"},{"q":"SOX primarily drives requirements around:","opts":["UI color accessibility","Marketing campaign performance","Integrity and auditability of financial reporting and the controls over it","Social media engagement"],"a":2,"exp":"Sarbanes-Oxley targets accuracy/integrity of financial reporting and internal controls. BAs capture control, segregation-of-duties, and audit requirements.","competency":"ba:compliance"},{"q":"For a SOX-relevant financial system, the most essential control requirement is:","opts":["Segregation of duties plus an immutable audit trail of changes to financial data","Faster page load times","A dark-mode theme","More email notifications"],"a":0,"exp":"SOX hinges on preventing/detecting improper changes to financial data: segregation of duties + tamper-evident audit trails are core control requirements.","competency":"ba:compliance"},{"q":"The purpose of an audit-trail requirement is to:","opts":["Reduce storage costs","Improve the UI","Speed up the database","Record who did what, when, and to which data, in a tamper-evident way"],"a":3,"exp":"Audit trails provide accountability and traceability (who/what/when/which-record), tamper-evident, to satisfy regulators and investigations.","competency":"ba:compliance"},{"q":"A stakeholder asks to let admins edit audit logs to \"fix mistakes.\" The BA should:","opts":["Allow deletion of old entries","Reject editable logs; specify append-only, immutable logging with corrections as new attributed entries","Allow edits to keep logs clean","Make logging optional"],"a":1,"exp":"Editable logs defeat their purpose and violate most regimes. Logs must be append-only/immutable; corrections are new entries, never overwrites.","competency":"ba:compliance"},{"q":"In compliance terms, a \"control\" is:","opts":["A type of stakeholder","A safeguard or procedure that reduces a specific risk to an acceptable level","A project milestone","A UI button"],"a":1,"exp":"A control is a preventive/detective/corrective safeguard mitigating a defined risk. BAs map requirements to the controls addressing regulatory risk.","competency":"ba:compliance"},{"q":"To demonstrate a system meets a regulation, the most defensible BA approach is to:","opts":["Map each obligation to a specific control and to the requirement/test that evidences it","Rely on the vendor''s brochure","Assert compliance in a summary email","Wait for an audit to find gaps"],"a":0,"exp":"Defensible compliance traces obligation → control → requirement → evidence. This mapping is auditable and surfaces gaps proactively.","competency":"ba:compliance"},{"q":"A data-retention requirement specifies:","opts":["How fast data loads","The dashboard color scheme","How long data is kept and when/how it is securely deleted","The database vendor"],"a":2,"exp":"Retention requirements define retention periods and secure disposal, balancing legal minimums against storage-limitation principles.","competency":"ba:compliance"},{"q":"GDPR storage limitation and a 7-year financial-record law seem to conflict for one dataset. The BA should:","opts":["Delete everything after 30 days","Separate data by purpose and apply the specific lawful retention to each","Keep everything for 7 years to be safe","Ignore one regulation"],"a":1,"exp":"Different data has different lawful bases. Scope retention per category/purpose — financial records per statute, other personal data per its basis — not a blanket rule.","competency":"ba:compliance"},{"q":"\"Privacy by design\" means the BA should:","opts":["Leave privacy to the legal team only","Collect data first and restrict it later","Add a privacy-policy page at the end","Build privacy controls into requirements from the start, not bolt them on later"],"a":3,"exp":"Privacy by design (GDPR Art. 25) embeds privacy into requirements/architecture from inception — minimal-default data, purpose limitation, designed-in controls.","competency":"ba:compliance"},{"q":"When is a Data Protection Impact Assessment (DPIA) most clearly required, and the BA''s role?","opts":["Only after a breach; the BA has no role","For high-risk processing (large-scale sensitive data/profiling); the BA maps processing, risks, and mitigations into requirements","Only for marketing emails","Never — it''s purely legal"],"a":1,"exp":"A DPIA is required for high-risk processing (GDPR Art. 35). BAs map the processing, surface risks, and translate mitigations into requirements/controls.","competency":"ba:compliance"},{"q":"When eliciting compliance requirements, the BA''s best primary sources are:","opts":["Competitor websites","Social-media trends","The applicable regulations/standards plus compliance, legal, and audit stakeholders","Developer preferences"],"a":2,"exp":"Compliance requirements come from the regulations themselves and the accountable people (compliance/legal/audit/DPO), not informal sources.","competency":"ba:compliance"},{"q":"A stakeholder says \"just make it compliant.\" The BA''s most effective next step is to:","opts":["Assume GDPR covers everything","Identify which regulations apply, then elicit concrete obligations and controls with compliance/legal SMEs","Defer until testing","Add a \"compliance\" checkbox to the UI"],"a":1,"exp":"\"Compliant\" is not a requirement. Determine applicable regimes (by data/geography/industry) and translate each into specific, testable obligations with accountable SMEs.","competency":"ba:compliance"},{"q":"A compliance traceability matrix helps at audit time because it:","opts":["Lists all developers","Stores user passwords","Links each obligation to the requirement, control, and test evidence that satisfies it","Tracks sprint velocity"],"a":2,"exp":"It maps obligation → requirement → control → evidence, giving auditors a defensible, complete line of sight and exposing unmet obligations.","competency":"ba:compliance"},{"q":"During validation, a BA finds an obligation with a requirement but no implemented control and no test evidence. The correct conclusion is:","opts":["It''s the auditor''s problem","It''s fine because a requirement was written","The obligation is unverified / non-compliant — flag it as a gap until a control and passing evidence exist","Mark it compliant and move on"],"a":2,"exp":"A written requirement without an effective, evidenced control is an open compliance gap. Validation requires evidence of an effective control, not just documentation.","competency":"ba:compliance"}]'::jsonb);

DROP FUNCTION pg_temp.fill_ba_exam(int, jsonb);

